const BOOKS = [
{
    t: "I. Kinh điển",
    n: 62,
    items: [
      ["Đồi Thỏ", "Richard Adams", null, "Watership Down kể về hành trình của một nhóm thỏ rời bỏ hang ổ bị đe dọa phá hủy để tìm một nơi ở mới an toàn hơn. Trên đường đi chúng đối mặt hiểm nguy từ thiên nhiên, kẻ săn mồi và cả những xã hội thỏ khác có luật lệ hà khắc. Tác phẩm mang dáng dấp sử thi phiêu lưu dành cho thiếu nhi nhưng ẩn chứa suy tưởng sâu sắc về tự do, lãnh đạo và bản chất cộng đồng."],
      ["Người Đàn Ông Mỹ Cuối Cùng", "Elizabeth Gilbert", undefined, "Cuốn sách kể lại chân dung Eustace Conway, một người đàn ông từ bỏ cuộc sống hiện đại để vào rừng Appalachia sống theo lối nguyên thủy, tự cung tự cấp. Qua ngòi bút phi hư cấu, Elizabeth Gilbert khắc họa hành trình từ tuổi thơ đến khi Conway trở thành biểu tượng của tinh thần khai hoang và tự do kiểu Mỹ. Tác phẩm đồng thời đặt câu hỏi về ý nghĩa của nam tính, sự hoang dã và vị trí của con người trong xã hội công nghiệp hóa."],
      ["Walden - Một Mình Ở Trong Rừng", "Henry David Thoreau", undefined, "Walden là tập ghi chép của Henry David Thoreau về hai năm ông sống đơn độc trong một căn lều tự dựng bên hồ Walden, Massachusetts. Qua đó tác giả suy ngẫm về lối sống giản dị, tự cung tự cấp và mối quan hệ gần gũi với thiên nhiên. Tác phẩm trở thành một trong những áng văn kinh điển về triết lý sống tối giản và tinh thần độc lập của con người Mỹ."],
      ["Tôi, Charley Và Hành Trình Nước Mỹ", "John Steinbeck", undefined, "Cuốn sách ghi lại chuyến du hành xuyên nước Mỹ của John Steinbeck cùng chú chó poodle Charley trên một chiếc xe tải cắm trại. Qua các cuộc gặp gỡ tình cờ với người dân dọc đường, tác giả quan sát và suy ngẫm về những đổi thay của xã hội, văn hóa và cảnh quan nước Mỹ vào đầu thập niên 1960. Đây là tác phẩm phi hư cấu pha trộn giữa du ký và chiêm nghiệm cá nhân về bản sắc dân tộc Mỹ."],
      ["The Drifters - 6 Người Đi Khắp Thế Gian", "James A. Michener", undefined, "Tiểu thuyết kể về sáu người trẻ đến từ nhiều quốc gia khác nhau, mỗi người mang một nỗi bất mãn hoặc tổn thương riêng, tình cờ gặp nhau tại thị trấn Torremolinos của Tây Ban Nha. Họ cùng nhau lang thang qua nhiều vùng đất ở châu Âu và châu Phi, tìm kiếm ý nghĩa sống giữa bối cảnh biến động của cuối thập niên 1960. Qua các nhân vật, James A. Michener khắc họa tinh thần phản kháng, khủng hoảng bản sắc và khát vọng tự do của thế hệ trẻ thời kỳ đó."],
      ["Thiền Và Nghệ Thuật Bảo Dưỡng Xe Máy", "Robert M. Pirsig", undefined, "Cuốn sách kể về chuyến đi xe máy xuyên nước Mỹ của người cha cùng con trai, đan xen giữa câu chuyện hành trình và những suy tưởng triết học sâu sắc. Qua việc bảo dưỡng chiếc xe máy, tác giả Robert M. Pirsig khai triển khái niệm về \"chất lượng\" (Quality) và mối liên hệ giữa tư duy duy lý phương Tây với triết lý phương Đông. Tác phẩm pha trộn tự truyện, triết học và du ký, trở thành một trong những cuốn sách triết học phổ thông có ảnh hưởng lớn của thế kỷ 20."],
      ["Suối Nguồn", "Ayn Rand", undefined, "Tiểu thuyết xoay quanh Howard Roark, một kiến trúc sư trẻ kiên định theo đuổi lý tưởng sáng tạo cá nhân bất chấp áp lực phải thỏa hiệp với thị hiếu đám đông. Đối lập với Roark là những nhân vật đại diện cho chủ nghĩa a dua và khát khao quyền lực thông qua việc điều khiển người khác. Qua tác phẩm, Ayn Rand trình bày triết lý chủ nghĩa khách quan, đề cao chủ nghĩa cá nhân và tinh thần độc lập sáng tạo."],
      ["Forrest Gump", "Winston Groom", undefined, "Tiểu thuyết kể về Forrest Gump, một chàng trai có chỉ số IQ thấp nhưng sở hữu lòng tốt và nghị lực phi thường, vô tình chứng kiến và tham gia vào nhiều sự kiện lớn của lịch sử nước Mỹ. Từ chiến tranh Việt Nam, bóng bầu dục đại học đến các sự kiện chính trị, Forrest trải qua một hành trình đời đầy bất ngờ với giọng kể hài hước, mộc mạc. Tác phẩm là nguồn cảm hứng cho bộ phim cùng tên nổi tiếng, ca ngợi sự chân thành và lòng kiên trì giữa những biến động của thời cuộc."],
      ["Ba Gã Cùng Thuyền", "Jerome K. Jerome", undefined, "Cuốn sách kể về chuyến đi chèo thuyền trên sông Thames của ba người bạn cùng chú chó Montmorency, vốn dự định là một kỳ nghỉ thư giãn để chữa bệnh tưởng tượng. Trên hành trình, họ liên tục gặp phải những tình huống dở khóc dở cười do sự vụng về và tính cách lười biếng của chính mình. Bằng giọng văn hài hước châm biếm, Jerome K. Jerome khắc họa sinh động đời sống thường nhật và thói quen của tầng lớp trung lưu Anh cuối thế kỷ 19."],
      ["Anne Tóc Đỏ Dưới Chái Nhà Xanh", "L.M. Montgomery", undefined, "Câu chuyện kể về Anne Shirley, một cô bé mồ côi tóc đỏ giàu trí tưởng tượng, được một cặp anh em lớn tuổi ở đảo Prince Edward nhận nuôi dù ban đầu họ mong muốn một cậu bé. Với tính cách bộc trực và tâm hồn bay bổng, Anne dần chinh phục những người xung quanh và trưởng thành qua nhiều biến cố ở trường học và cộng đồng nhỏ Avonlea. Tác phẩm là một trong những tiểu thuyết thiếu nhi kinh điển của văn học Canada, ca ngợi trí tưởng tượng, lòng nhân hậu và nghị lực vươn lên."],
      ["Những Kỳ Vọng Lớn Lao", "Charles Dickens", undefined, "Tiểu thuyết kể về Pip, một cậu bé mồ côi nghèo khó bất ngờ nhận được khoản tài trợ bí ẩn cho phép cậu trở thành một quý ông ở London. Trong quá trình theo đuổi địa vị và tình yêu với Estella, Pip dần khám phá ra sự thật về ân nhân của mình cũng như bản chất thật của tham vọng và giai cấp xã hội. Charles Dickens sử dụng câu chuyện để phê phán sự phù phiếm của tầng lớp thượng lưu Anh thời Victoria và đề cao giá trị đạo đức chân chính."],
      ["Trên Đường", "Jack Kerouac", undefined, "Tiểu thuyết bán tự truyện kể về những chuyến đi xuyên nước Mỹ của Sal Paradise cùng người bạn phóng túng Dean Moriarty, tìm kiếm tự do và trải nghiệm sống ngoài khuôn khổ xã hội. Tác phẩm phản ánh tinh thần của thế hệ Beat những năm 1950 với nhạc jazz, thơ ca, ma túy và khát vọng xê dịch không ngừng. Với lối viết tự phát, giàu nhịp điệu, Jack Kerouac đã tạo nên một biểu tượng văn học cho tinh thần phản kháng và tự do cá nhân."],
      ["Người Đua Diều", "Khaled Hosseini", undefined, "Tiểu thuyết kể về Amir, một cậu bé người Afghanistan, và mối quan hệ phức tạp với Hassan, con trai người hầu trung thành của gia đình cậu, trước biến cố khiến Amir phản bội bạn mình. Nhiều năm sau khi đã sang Mỹ định cư, Amir trở lại Afghanistan dưới thời Taliban để chuộc lại lỗi lầm quá khứ. Khaled Hosseini khắc họa bối cảnh lịch sử đầy biến động của Afghanistan song song với hành trình cứu chuộc và tình bạn, tình cha con."],
      ["Little Women, Good Wives", "Louisa May Alcott", undefined, "Tác phẩm kể về bốn chị em nhà March - Meg, Jo, Beth và Amy - lớn lên trong một gia đình trung lưu ở New England thời nội chiến Mỹ, khi cha họ vắng nhà vì chiến tranh. Mỗi người theo đuổi những ước mơ, tính cách và số phận riêng, từ khát vọng viết văn của Jo đến cuộc sống hôn nhân của Meg và Amy trong phần tiếp theo \"Good Wives\". Tác phẩm ca ngợi tình thân, lòng nhân hậu và sự trưởng thành của người phụ nữ trong khuôn khổ giá trị gia đình thế kỷ 19."],
      ["Của Chuột Và Người", "John Steinbeck", undefined, "Tiểu thuyết ngắn kể về George và Lennie, hai người lao động lang thang thời kỳ Đại khủng hoảng ở Mỹ, cùng nhau mơ về một mảnh đất riêng để canh tác. Lennie có sức khỏe phi thường nhưng trí tuệ hạn chế, thường gây ra rắc rối không cố ý mà George phải gánh chịu hậu quả thay. Qua bi kịch của hai nhân vật, John Steinbeck phản ánh sự cô đơn, giấc mơ Mỹ dang dở và số phận bấp bênh của tầng lớp lao động nghèo."],
      ["Bắt Trẻ Đồng Xanh", "J.D. Salinger", undefined, "Tiểu thuyết kể về Holden Caulfield, một thiếu niên bị đuổi học, lang thang khắp New York trong vài ngày và quan sát thế giới người lớn bằng cái nhìn hoài nghi, chán ghét sự giả tạo. Qua dòng độc thoại nội tâm, Holden bộc lộ sự cô đơn, hoang mang tuổi mới lớn và khao khát bảo vệ sự trong sáng của trẻ nhỏ trước những cạm bẫy cuộc đời. Tác phẩm trở thành biểu tượng văn học về khủng hoảng tuổi vị thành niên trong xã hội Mỹ thế kỷ 20."],
      ["Bay Trên Tổ Chim Cúc Cu", "Ken Kesey", undefined, "Câu chuyện diễn ra trong một bệnh viện tâm thần, nơi McMurphy, một bệnh nhân giả điên để trốn lao động khổ sai, khơi dậy tinh thần phản kháng của các bệnh nhân khác trước sự cai trị hà khắc của y tá trưởng Ratched. Cuộc đối đầu giữa McMurphy và hệ thống quyền lực trong bệnh viện dần trở thành biểu tượng cho xung đột giữa cá nhân tự do và bộ máy kiểm soát xã hội. Ken Kesey xây dựng tác phẩm như một lời phê phán mạnh mẽ đối với các thiết chế áp bức và sự chuẩn hóa con người."],
      ["Chúa Ruồi", "William Golding", undefined, "Tiểu thuyết kể về một nhóm trẻ em Anh bị mắc kẹt trên một hoang đảo sau tai nạn máy bay, ban đầu cố gắng tự tổ chức xã hội văn minh nhưng dần trượt vào bạo lực và man rợ. Sự phân rã giữa các nhóm trẻ, đặc biệt là giữa Ralph đại diện cho trật tự và Jack đại diện cho bản năng hoang dã, đẩy câu chuyện đến bi kịch đẫm máu. William Golding dùng câu chuyện để khám phá bản chất tăm tối tiềm ẩn trong con người khi không còn ràng buộc của văn minh."],
      ["Chiến Binh Cầu Vồng", "Andrea Hirata", undefined, "Tiểu thuyết kể về mười học sinh nghèo tại một ngôi trường làng ọp ẹp trên đảo Belitong, Indonesia, cùng hai người thầy tận tụy quyết tâm duy trì việc học giữa muôn vàn thiếu thốn. Nhóm học trò tự gọi mình là \"Chiến binh Cầu vồng\", cùng nhau vượt qua nghịch cảnh, đói nghèo và sự thờ ơ của xã hội để theo đuổi tri thức. Dựa trên trải nghiệm của chính tác giả, cuốn sách ca ngợi nghị lực học tập, tình thầy trò và sức mạnh của giáo dục trong việc thay đổi số phận."],
      ["Chú Bé Mang Pyjama Sọc", "John Boyne", undefined, "Câu chuyện kể về Bruno, cậu bé chín tuổi con trai một sĩ quan Đức Quốc xã, chuyển đến sống gần một trại tập trung trong Thế chiến thứ hai mà không hiểu rõ bản chất nơi đó. Qua hàng rào trại, Bruno kết bạn với Shmuel, một cậu bé Do Thái cùng tuổi mặc bộ đồ sọc, và tình bạn ngây thơ giữa hai đứa trẻ dần dẫn đến một kết cục bi thảm. Tác phẩm nhìn nạn diệt chủng Holocaust qua lăng kính ngây thơ của trẻ nhỏ để làm nổi bật sự phi lý và tàn khốc của chiến tranh."],
      ["Những Đứa Con Của Tự Do", "Marc Levy", undefined, "Tiểu thuyết dựa trên câu chuyện có thật về một nhóm thanh niên nhập cư, phần lớn là người Do Thái và cộng sản, tham gia phong trào kháng chiến chống phát xít Đức tại Toulouse, Pháp trong Thế chiến thứ hai. Họ thực hiện các hoạt động phá hoại, ám sát và tình báo với cái giá phải trả là mạng sống của chính mình khi bị bắt giữ và xử tử. Marc Levy tái hiện lòng dũng cảm, tình yêu và sự hy sinh của những chiến sĩ trẻ tuổi vô danh trong cuộc chiến giành tự do."],
      ["Vừa Nhắm Mắt Vừa Mở Cửa Sổ", "Nguyễn Ngọc Thuần", undefined, "Cuốn sách kể theo lời một cậu bé sống ở một làng quê, nơi người cha dạy con cách cảm nhận thế giới bằng cả các giác quan, như nhắm mắt để ngửi hương hoa hay đoán tên loài cây qua xúc giác. Song song đó là tình cảm trong sáng giữa cậu bé và bé Thắm, cô bé hàng xóm bị tai nạn làm biến dạng khuôn mặt nhưng luôn được cậu yêu thương trân trọng. Tác phẩm mang giọng văn nhẹ nhàng, giàu chất thơ, ca ngợi tình cha con, tình làng xóm và cách nhìn đời hồn nhiên, nhân hậu của trẻ thơ."],
      ["Hoàng Tử Bé", "Antoine De Saint-Exupéry", undefined, "Câu chuyện kể về cuộc gặp gỡ giữa một phi công bị rơi máy bay giữa sa mạc Sahara và hoàng tử bé đến từ một hành tinh nhỏ xa xôi. Qua lời kể của hoàng tử bé về những hành tinh kỳ lạ mà cậu từng ghé qua và bông hồng cậu để lại ở quê nhà, tác phẩm gửi gắm nhiều suy ngẫm về tình yêu, sự cô đơn và cách nhìn nhận thế giới của người lớn. Với văn phong giản dị pha lẫn ẩn dụ sâu sắc, cuốn sách trở thành một trong những tác phẩm văn học Pháp được yêu thích nhất mọi thời đại."],
      ["Khi Hơi Thở Hóa Thinh Không", "Paul Kalanithi", undefined, "Cuốn hồi ký được viết bởi Paul Kalanithi, một bác sĩ phẫu thuật thần kinh tài năng, khi ông phát hiện mắc ung thư phổi giai đoạn cuối ở tuổi ngoài ba mươi. Tác phẩm ghi lại hành trình ông đối diện với cái chết, chuyển từ vai trò bác sĩ chữa bệnh sang vai trò bệnh nhân, đồng thời suy ngẫm về ý nghĩa của sự sống, nghề y và cái chết. Cuốn sách được hoàn thành dang dở và xuất bản sau khi ông qua đời, để lại thông điệp sâu sắc về lòng can đảm và giá trị của thời gian còn lại."],
      ["Nơi Dòng Sông Chảy Qua", "Norman Maclean", undefined, "Tiểu thuyết bán tự truyện kể về hai anh em Norman và Paul Maclean lớn lên ở Montana, gắn bó với nhau qua niềm đam mê câu cá bằng ruồi giả (fly-fishing) trên dòng sông quê hương. Trong khi Norman theo đuổi con đường học vấn ổn định, Paul lại có cuộc sống phóng túng và dần trượt vào những rắc rối dẫn đến bi kịch. Tác phẩm là bản tình ca về thiên nhiên, gia đình và nỗi day dứt của người anh trước số phận người em mà mình không thể cứu giúp."],
      ["Tất Cả Các Dòng Sông Đều Chảy", "Nancy Cato", undefined, "Tiểu thuyết kể về cuộc đời Delie Gordon, một cô gái mồ côi lớn lên bên dòng sông Murray ở Úc vào cuối thế kỷ 19, người đam mê hội họa và khao khát tự lập. Delie trở thành người phụ nữ điều khiển tàu hơi nước trên sông, trải qua tình yêu, mất mát và những thăng trầm trong một xã hội còn nhiều định kiến với phụ nữ. Tác phẩm khắc họa sinh động đời sống trên các con sông nước Úc cùng nghị lực vươn lên của một người phụ nữ độc lập."],
      ["Chùm Nho Phẫn Nộ", "John Steinbeck", undefined, "Tiểu thuyết kể về gia đình Joad, những nông dân nghèo ở Oklahoma buộc phải rời bỏ vùng đất khô cằn trong thời kỳ Dust Bowl để di cư sang California tìm việc làm. Trên hành trình, họ phải đối mặt với đói nghèo, bóc lột và sự thờ ơ của xã hội dành cho những người lao động nhập cư. John Steinbeck dùng câu chuyện để phê phán bất công xã hội thời Đại khủng hoảng và ca ngợi tinh thần đoàn kết, kiên cường của tầng lớp lao động."],
      ["Trăm Năm Cô Đơn", "Gabriel García Márquez", undefined, "Tiểu thuyết kể về bảy thế hệ dòng họ Buendía tại thị trấn hư cấu Macondo, nơi hiện thực và huyền ảo đan xen qua những sự kiện kỳ lạ lặp lại theo vòng xoáy định mệnh. Các nhân vật trải qua chiến tranh, tình yêu, cô đơn và những ám ảnh mang tính biểu tượng, phản ánh lịch sử đầy biến động của Mỹ Latinh. Gabriel García Márquez được xem là người khai sinh trường phái hiện thực huyền ảo qua kiệt tác này."],
      ["Con Đường Hồi Giáo", "Phương Mai Nguyễn", undefined, "Cuốn sách ghi lại hành trình của tác giả Nguyễn Phương Mai qua nhiều quốc gia Hồi giáo ở Trung Đông và Bắc Phi để tìm hiểu về văn hóa, tôn giáo và đời sống thường nhật của người dân nơi đây. Bằng góc nhìn của một nhà nghiên cứu kiêm nhà báo, tác giả cố gắng lý giải những hiểu lầm phổ biến về đạo Hồi và thế giới Ả Rập trong con mắt phương Tây lẫn Việt Nam. Tác phẩm kết hợp giữa du ký, phân tích văn hóa - chính trị và trải nghiệm cá nhân để mang đến cái nhìn đa chiều hơn về khu vực này."],
      ["Hành Trình Về Phương Đông", "Baird T. Spalding", undefined, "Cuốn sách kể về một đoàn khoa học gia phương Tây thực hiện chuyến khảo sát đến Ấn Độ, Tây Tạng nhằm nghiên cứu những hiện tượng huyền bí và các vị thầy tâm linh phương Đông. Qua các cuộc gặp gỡ với những bậc thầy có khả năng phi thường, đoàn khảo sát dần thay đổi nhận thức, từ hoài nghi khoa học sang chiêm nghiệm về mối liên hệ giữa tâm linh, năng lượng và vũ trụ. Tác phẩm mang màu sắc huyền học, được xem là một trong những cuốn sách gối đầu giường về hành trình tìm kiếm minh triết phương Đông."],
      ["Hải Trình Kon-Tiki", "Thor Heyerdahl", undefined, "Cuốn sách ghi lại chuyến hải trình có thật của Thor Heyerdahl cùng năm cộng sự vượt Thái Bình Dương từ Peru đến quần đảo Polynesia trên một chiếc bè gỗ balsa thô sơ mang tên Kon-Tiki. Chuyến đi nhằm chứng minh giả thuyết rằng cư dân cổ đại Nam Mỹ có thể đã di cư đến các đảo Thái Bình Dương bằng phương tiện thô sơ. Tác phẩm kể lại những hiểm nguy trên biển cùng tinh thần phiêu lưu, khoa học thực nghiệm táo bạo của đoàn thám hiểm."],
      ["Vào Trong Hoang Dã", "Jon Krakauer", undefined, "Cuốn sách phi hư cấu kể về Christopher McCandless, một chàng trai trẻ tốt nghiệp đại học từ bỏ tài sản và các mối quan hệ để độc hành vào vùng hoang dã Alaska, tìm kiếm ý nghĩa sống tách biệt khỏi xã hội vật chất. Sau nhiều tháng sống một mình trong tự nhiên, anh qua đời vì đói và ngộ độc thực phẩm trong một chiếc xe buýt bỏ hoang. Jon Krakauer tái dựng hành trình và động cơ của McCandless qua các cuộc phỏng vấn, nhật ký, đặt ra câu hỏi về khát vọng tự do và giới hạn của con người trước thiên nhiên."],
      ["Hương Rừng Cà Mau", "Sơn Nam", undefined, "Tập truyện ngắn khắc họa đời sống của người dân vùng đất Cà Mau, miền cực nam Việt Nam, trong buổi đầu khai hoang lập ấp với những gian khổ, hiểm nguy từ rừng thiêng nước độc. Qua các nhân vật nông dân, thợ săn, người đi khai phá đất mới, Sơn Nam tái hiện phong tục, tín ngưỡng dân gian và tính cách phóng khoáng, nghĩa hiệp của con người Nam Bộ. Tác phẩm được xem là một trong những áng văn tiêu biểu nhất viết về vùng đất và con người miền Tây Nam Bộ."],
      ["Muôn Kiếp Nhân Sinh", "Nguyên Phong", undefined, "Cuốn sách kể về Thomas, một nhà tài phiệt phố Wall thành đạt nhưng luôn bị ám ảnh bởi những giấc mơ kỳ lạ, tìm đến phương pháp thôi miên hồi quy tiền kiếp để lý giải chúng. Qua các buổi trị liệu, ông dần nhớ lại nhiều kiếp sống trước đây trải dài qua các nền văn minh cổ đại như Ai Cập, Đại Tây Dương huyền thoại, từ đó nhận ra quy luật nhân quả chi phối đời sống hiện tại. Nguyên Phong chuyển thể tác phẩm với nhiều kiến giải về luật nhân quả, nghiệp báo và hành trình tiến hóa tâm linh của con người."],
      ["Cuộc Cách Mạng Một-Cọng-Rơm", "Masanobu Fukuoka", undefined, "Cuốn sách trình bày triết lý nông nghiệp tự nhiên của Masanobu Fukuoka, người đề xướng phương pháp canh tác không cày xới, không phân bón hóa học, không thuốc trừ sâu và không làm cỏ. Qua kinh nghiệm nhiều thập kỷ canh tác lúa và cây ăn quả trên nông trại của mình, ông chứng minh rằng con người có thể đạt năng suất bền vững bằng cách thuận theo tự nhiên thay vì can thiệp thô bạo vào nó. Tác phẩm không chỉ bàn về nông nghiệp mà còn mở rộng thành một triết lý sống tối giản, hòa hợp với tự nhiên."],
      ["Khởi Sinh Của Cô Độc", "Paul Auster", undefined, "Tác phẩm phi hư cấu được viết sau khi cha của Paul Auster qua đời đột ngột, mở đầu bằng những hồi tưởng về một người cha xa cách, khó nắm bắt trong suốt cuộc đời tác giả. Phần thứ hai của cuốn sách mở rộng thành những suy tưởng triết học về trí nhớ, sự cô độc, vai trò làm cha và bản chất của việc viết. Paul Auster đan xen tự truyện với suy tư văn chương để khám phá mối liên hệ giữa mất mát cá nhân và hành trình sáng tạo."],
      ["Rừng Na Uy", "Haruki Murakami", undefined, "Tiểu thuyết kể về Toru Watanabe, một sinh viên đại học ở Tokyo, hồi tưởng lại những năm tháng tuổi trẻ gắn với hai người phụ nữ mang tính cách trái ngược là Naoko mong manh và Midori sôi nổi. Câu chuyện xoay quanh nỗi ám ảnh về cái chết của người bạn thân thời niên thiếu, tình yêu, tình dục và sự mất mát trong bối cảnh nước Nhật cuối thập niên 1960. Haruki Murakami khắc họa nỗi cô đơn và sự trưởng thành đầy tổn thương của tuổi trẻ bằng văn phong trầm lắng, giàu nhạc tính."],
      ["Thiên Táng", "Xinran", undefined, "Cuốn sách kể lại câu chuyện có thật về Thư Văn, một nữ bác sĩ quân y Trung Quốc, người đã dành hơn ba mươi năm lang thang khắp cao nguyên Tây Tạng để tìm kiếm tung tích người chồng mất tích trong một cuộc xung đột quân sự. Trong hành trình tìm kiếm, bà sống cùng những bộ lạc du mục Tây Tạng, dần thấu hiểu văn hóa, tín ngưỡng và tục thiên táng của họ. Xinran tái hiện câu chuyện qua các cuộc phỏng vấn, khắc họa tình yêu bền bỉ và đời sống tâm linh độc đáo của người Tây Tạng."],
      ["Kiêu Hãnh Và Định Kiến", "Jane Austen", undefined, "Tiểu thuyết xoay quanh Elizabeth Bennet, một cô gái thông minh, sắc sảo thuộc gia đình trung lưu Anh, và mối quan hệ đầy va chạm ban đầu với ông Darcy giàu có nhưng kiêu ngạo. Qua những hiểu lầm, định kiến và va chạm giai cấp, hai người dần vượt qua cái tôi để đến với nhau. Jane Austen dùng câu chuyện tình yêu để châm biếm nhẹ nhàng các chuẩn mực hôn nhân, giai cấp và vai trò phụ nữ trong xã hội Anh thế kỷ 19."],
      ["Tiếng Chim Hót Trong Bụi Mận Gai", "Colleen McCullough", undefined, "Tiểu thuyết kể về gia đình Cleary trải qua nhiều thế hệ tại một trang trại hẻo lánh ở Úc, trọng tâm là mối tình cấm đoán kéo dài suốt đời giữa Meggie Cleary và vị linh mục Ralph de Bricassart. Câu chuyện lấy cảm hứng từ truyền thuyết loài chim mận gai tự đâm mình vào gai nhọn để cất tiếng hót hay nhất trước khi chết, ẩn dụ cho tình yêu phải trả giá bằng đau khổ. Tác phẩm trải dài qua nhiều thập kỷ, khắc họa số phận con người giữa khát vọng, tôn giáo và định mệnh."],
      ["Tội Ác Và Trừng Phạt", "Fyodor Dostoyevsky", undefined, "Tiểu thuyết kể về Raskolnikov, một sinh viên nghèo ở Saint Petersburg, người sát hại một bà cho vay nặng lãi với niềm tin rằng mình thuộc về loại người phi thường đứng trên luật lệ đạo đức thông thường. Sau tội ác, anh rơi vào trạng thái dằn vặt tâm lý dữ dội, vừa sợ bị phát hiện vừa bị lương tâm cắn rứt không nguôi. Dostoyevsky khai thác sâu tâm lý tội lỗi, sự cứu chuộc và các vấn đề triết học - đạo đức về giới hạn quyền lực cá nhân."],
      ["Phía Đông Vườn Địa Đàng", "John Steinbeck", undefined, "Tiểu thuyết kể về hai gia đình Trask và Hamilton tại thung lũng Salinas, California, xoay quanh mối quan hệ đầy xung đột giữa hai anh em Adam và Charles Trask, rồi sau đó là hai con trai của Adam là Aron và Caleb. Câu chuyện mượn cấu trúc và biểu tượng từ tích Cain và Abel trong Kinh Thánh để khai thác chủ đề thiện - ác, tự do ý chí và sự công nhận của người cha. John Steinbeck dựng nên một bức tranh sử thi nhiều thế hệ về bản chất con người và khả năng lựa chọn giữa thiện và ác."],
      ["Giết Con Chim Nhại", "Harper Lee", undefined, "Tiểu thuyết kể qua lời cô bé Scout Finch về vụ án luật sư Atticus Finch, cha cô, bào chữa cho một người đàn ông da đen bị buộc tội oan hãm hiếp một phụ nữ da trắng tại một thị trấn miền Nam nước Mỹ thời kỳ phân biệt chủng tộc. Qua phiên tòa và cuộc sống thường nhật, Scout và anh trai Jem dần nhận ra sự bất công, định kiến chủng tộc ăn sâu trong xã hội xung quanh mình. Harper Lee đề cao lòng chính trực, sự cảm thông và tinh thần đấu tranh cho công lý qua nhân vật Atticus Finch."],
      ["Brokeback Mountain", "Annie Proulx", undefined, "Truyện ngắn kể về Ennis Del Mar và Jack Twist, hai chàng chăn cừu trẻ tuổi nảy sinh tình cảm với nhau trong một mùa hè chăn thả gia súc trên núi Brokeback ở Wyoming. Dù sau đó mỗi người lập gia đình riêng theo chuẩn mực xã hội, họ vẫn duy trì mối quan hệ bí mật kéo dài suốt nhiều năm giữa những định kiến khắc nghiệt của thời đại. Annie Proulx khắc họa bi kịch của tình yêu đồng giới bị kìm nén trong bối cảnh nông thôn Mỹ bảo thủ giữa thế kỷ 20."],
      ["Người Khổng Lồ Nghiêng Vai", "Ayn Rand", "Chưa đọc", "Tiểu thuyết dựng nên một nước Mỹ trong khủng hoảng khi hàng loạt doanh nhân, nhà phát minh và những người tài năng nhất lần lượt biến mất bí ẩn, khiến nền kinh tế dần sụp đổ. Nhân vật chính Dagny Taggart, một nữ giám đốc đường sắt, cố gắng tìm hiểu nguyên nhân đứng sau sự biến mất này trong khi cố gắng cứu vãn công ty của gia đình. Ayn Rand sử dụng câu chuyện để trình bày triết lý chủ nghĩa khách quan, đề cao vai trò của những cá nhân sáng tạo và phê phán chủ nghĩa tập thể can thiệp vào tự do kinh tế."],
      ["Bố Già", "Mario Puzo", undefined, "Tiểu thuyết kể về gia tộc Corleone, một trong những gia đình mafia quyền lực nhất New York, đứng đầu là Don Vito Corleone và sau này là con trai Michael. Câu chuyện xoay quanh các cuộc tranh giành quyền lực, thù hận giữa các băng đảng và quá trình Michael, từ một người ngoài cuộc, dần trở thành người kế thừa lạnh lùng và tàn nhẫn của gia tộc. Mario Puzo khắc họa thế giới ngầm tội phạm có tổ chức cùng những quy tắc danh dự, trung thành và bạo lực riêng của nó."],
      ["Hãy Chăm Sóc Mẹ", "Shin Kyung-Sook", undefined, "Câu chuyện bắt đầu khi người mẹ trong một gia đình Hàn Quốc bị lạc mất tại nhà ga tàu điện ngầm ở Seoul, khiến các thành viên trong gia đình đổ xô tìm kiếm bà. Qua lời kể luân phiên của người chồng, các con và chính người mẹ, cuốn sách dần hé lộ những hy sinh thầm lặng, ước mơ dang dở và tình yêu vô điều kiện mà người mẹ đã dành cho gia đình nhưng ít khi được thấu hiểu. Shin Kyung-Sook khắc họa sâu sắc tình mẫu tử và sự day dứt, ân hận của những người ở lại khi nhận ra giá trị của người thân lúc đã muộn màng."],
      ["Đại Gia Gatsby", "F. Scott Fitzgerald", undefined, "Tiểu thuyết kể về Jay Gatsby, một triệu phú bí ẩn tổ chức những bữa tiệc xa hoa tại Long Island với hy vọng giành lại tình yêu thời trẻ là Daisy Buchanan, hiện đã kết hôn với người khác. Qua lời kể của Nick Carraway, hàng xóm của Gatsby, câu chuyện dần hé lộ sự thật về quá khứ và những ảo tưởng của Gatsby về giấc mơ Mỹ. F. Scott Fitzgerald phê phán sự phù phiếm, giả dối của giới thượng lưu Mỹ thời đại nhạc Jazz những năm 1920."],
      ["Ông Trăm Tuổi Trèo Qua Cửa Sổ Và Biến Mất", "Jonas Jonasson", undefined, "Tiểu thuyết kể về Allan Karlsson, một cụ ông vừa tròn một trăm tuổi, trèo qua cửa sổ viện dưỡng lão để trốn khỏi bữa tiệc sinh nhật và vô tình rơi vào một chuỗi phiêu lưu ly kỳ liên quan đến một băng đảng tội phạm. Đan xen với hành trình hiện tại là hồi ức về cuộc đời phi thường của Allan, người từng vô tình dự phần vào nhiều sự kiện lịch sử lớn của thế kỷ 20 khắp thế giới. Jonas Jonasson dùng giọng văn hài hước, châm biếm để kể lại một câu chuyện phiêu lưu pha trộn giữa hư cấu và các sự kiện lịch sử có thật."],
      ["Cloud Atlas", "David Mitchell", undefined, "Tiểu thuyết gồm sáu câu chuyện lồng ghép nhau, trải dài từ quá khứ thế kỷ 19 đến tương lai hậu tận thế, mỗi câu chuyện có nhân vật, bối cảnh và thể loại văn phong riêng biệt. Các câu chuyện được kết nối với nhau qua những chi tiết tinh tế như một vết bớt hình sao chổi, gợi ý về sự luân hồi và mối liên hệ xuyên thời gian giữa các linh hồn. David Mitchell khai thác chủ đề về quyền lực, sự áp bức và khả năng lặp lại của lịch sử qua cấu trúc tự sự độc đáo, lồng ghép nhiều thể loại."],
      ["Nhà Giả Kim", "Paulo Coelho", undefined, "Tiểu thuyết kể về Santiago, một chàng chăn cừu người Tây Ban Nha, lên đường đến kim tự tháp Ai Cập sau khi liên tục có giấc mơ báo hiệu về một kho báu chôn giấu nơi đó. Trên hành trình, cậu gặp gỡ nhiều nhân vật như vua Salem, nhà giả kim, mỗi người truyền dạy cho cậu những bài học về việc lắng nghe trái tim và theo đuổi \"vận mệnh cá nhân\" (Personal Legend) của mình. Paulo Coelho gửi gắm thông điệp về ý nghĩa của hành trình theo đuổi ước mơ và những dấu hiệu của vũ trụ dẫn dắt con người."],
      ["Lại Thằng Nhóc Emil!", "Astrid Lindgren", undefined, "Cuốn sách tiếp nối loạt truyện về Emil, cậu bé nông dân tinh nghịch sống ở vùng nông thôn Thụy Điển đầu thế kỷ 20, thường xuyên gây ra những trò nghịch ngợm khiến cả làng phải bàn tán. Dù thường bị nhốt trong nhà kho như hình phạt, Emil luôn có ý định tốt đằng sau mỗi trò nghịch của mình và được lòng người dân trong vùng. Astrid Lindgren kể chuyện bằng giọng văn hài hước, ấm áp, khắc họa đời sống nông thôn Bắc Âu và tuổi thơ tinh nghịch nhưng giàu tình cảm."],
      ["Cánh Đồng Bất Tận", "Nguyễn Ngọc Tư", undefined, "Truyện kể về một người cha cùng hai con nhỏ, Nương và Điền, sống lênh đênh trên chiếc ghe giữa những cánh đồng miền Tây Nam Bộ sau khi người mẹ bỏ nhà theo tình nhân. Mang nỗi cay đắng và hoài nghi về tình yêu, người cha trở nên lạnh lùng, thậm chí tàn nhẫn, khiến hai đứa con phải lớn lên trong thiếu thốn tình cảm và chứng kiến nhiều biến cố đau lòng. Nguyễn Ngọc Tư khắc họa chân thực đời sống nghèo khó, cô độc của con người miền sông nước cùng những vết thương tâm lý khó lành."],
      ["Trại Súc Vật", "George Orwell", undefined, "Câu chuyện ngụ ngôn kể về các loài vật trong một trang trại nổi dậy lật đổ người chủ để tự quản lý, với lý tưởng ban đầu về một xã hội bình đẳng, không có áp bức. Tuy nhiên, đàn lợn dần thâu tóm quyền lực, bóp méo các nguyên tắc ban đầu và thiết lập một chế độ độc tài không khác gì con người mà chúng từng lật đổ. George Orwell dùng câu chuyện ngụ ngôn này để phúng dụ cuộc Cách mạng Nga và phê phán sự tha hóa quyền lực trong các chế độ toàn trị."],
      ["1984", "George Orwell", undefined, "Tiểu thuyết dựng nên một xã hội toàn trị tương lai nơi Đảng cầm quyền do Anh Cả (Big Brother) đứng đầu kiểm soát mọi khía cạnh đời sống người dân, kể cả tư tưởng, thông qua giám sát và tuyên truyền. Nhân vật chính Winston Smith làm việc tại Bộ Sự Thật, nơi chuyên sửa đổi lịch sử, nhưng bí mật nuôi dưỡng tư tưởng phản kháng và tình yêu cấm đoán với Julia. George Orwell cảnh báo về nguy cơ của chế độ toàn trị, sự thao túng ngôn ngữ và sự thật, đồng thời khắc họa số phận bi kịch của cá nhân trước bộ máy quyền lực tuyệt đối."],
      ["Chết Ở Venice", "Thomas Mann", undefined, "Truyện vừa kể về Gustav von Aschenbach, một nhà văn lớn tuổi người Đức, đến Venice nghỉ dưỡng và nảy sinh nỗi say mê ám ảnh với vẻ đẹp của Tadzio, một cậu bé Ba Lan mà ông chỉ dám ngắm nhìn từ xa. Trong khi dịch tả bắt đầu lan tràn khắp thành phố, Aschenbach vẫn chìm đắm trong nỗi si mê, phớt lờ mọi nguy hiểm để được ở gần Tadzio. Thomas Mann khai thác chủ đề về cái đẹp, sự suy đồi đạo đức và ranh giới mong manh giữa nghệ thuật, dục vọng và cái chết."],
      ["Diary Of A Wimpy Kid", "Jeff Kinney", undefined, "Cuốn sách kể theo hình thức nhật ký minh họa của Greg Heffley, một cậu học sinh trung học cơ sở, ghi lại những rắc rối, ước mơ trở nên nổi tiếng và mối quan hệ dở khóc dở cười với bạn bè, anh trai và gia đình. Với giọng văn hài hước tự trào kết hợp tranh vẽ đơn giản, tác phẩm phản ánh chân thực những lo âu, hiểu lầm và tình huống dở khóc dở cười của tuổi mới lớn. Đây là cuốn đầu tiên trong loạt truyện ăn khách toàn cầu dành cho thiếu nhi và thanh thiếu niên."],
      ["Lịch Sử Khẩn Hoang Miền Nam", "Sơn Nam", undefined, "Công trình khảo cứu của Sơn Nam trình bày quá trình người Việt từ miền Trung, miền Bắc di dân vào khai phá vùng đất Nam Bộ từ thế kỷ 17, đối mặt với rừng rậm, thú dữ và điều kiện tự nhiên khắc nghiệt. Tác giả phân tích các đặc điểm về địa lý, kinh tế, xã hội và văn hóa hình thành trong quá trình khẩn hoang, cùng vai trò của các nhóm lưu dân, điền chủ trong việc định hình vùng đất mới. Cuốn sách là tài liệu tham khảo quan trọng về lịch sử khai phá và bản sắc văn hóa của vùng đồng bằng sông Cửu Long."],
      ["The Hidden Life Of Trees", "Peter Wohlleben", undefined, "Cuốn sách trình bày những phát hiện khoa học về đời sống cây rừng, cho thấy cây có khả năng giao tiếp, chia sẻ dinh dưỡng và hỗ trợ lẫn nhau thông qua mạng lưới rễ và nấm dưới lòng đất. Dựa trên kinh nghiệm nhiều năm làm việc trong ngành lâm nghiệp, Peter Wohlleben mô tả cách các khu rừng vận hành như một cộng đồng có tổ chức xã hội phức tạp hơn con người vẫn nghĩ. Tác phẩm khơi gợi cái nhìn mới về thiên nhiên, thúc đẩy ý thức bảo vệ rừng và tôn trọng sự sống của thực vật."],
      ["Educated", "Tara Westover", undefined, "Hồi ký kể về Tara Westover, lớn lên trong một gia đình theo chủ nghĩa sinh tồn cực đoan ở vùng núi Idaho, không được đến trường và bị cách ly khỏi hệ thống y tế, giáo dục chính thống. Bằng nghị lực tự học, cô thi đỗ đại học và dần bước vào một thế giới tri thức hoàn toàn khác biệt với môi trường gia đình đầy kiểm soát và bạo lực mà cô lớn lên. Tác phẩm khắc họa hành trình đấu tranh giữa lòng trung thành với gia đình và khát vọng tự do tri thức, bản sắc cá nhân."],
      ["Flow", "Mihaly Csikszentmihalyi", undefined, "Cuốn sách trình bày khái niệm \"dòng chảy\" (flow), trạng thái tâm lý khi con người hoàn toàn đắm chìm và tập trung cao độ vào một hoạt động đến mức quên đi thời gian và bản thân. Dựa trên nhiều nghiên cứu tâm lý học, Mihaly Csikszentmihalyi phân tích các điều kiện giúp con người đạt được trạng thái này, như sự cân bằng giữa thử thách và kỹ năng, mục tiêu rõ ràng và phản hồi tức thời. Tác phẩm được xem là nền tảng quan trọng của tâm lý học tích cực, gợi ý cách để đạt được hạnh phúc và sự hài lòng bền vững trong công việc, cuộc sống."],
      ["A Man Called Ove", "Fredrik Backman", undefined, "Tiểu thuyết kể về Ove, một người đàn ông lớn tuổi cau có, sống theo nguyên tắc cứng nhắc và luôn cảm thấy lạc lõng sau khi vợ qua đời, đang có ý định tự tử thì liên tục bị những người hàng xóm mới làm gián đoạn. Qua các tình huống dở khóc dở cười với gia đình hàng xóm mới chuyển đến, Ove dần mở lòng và xây dựng những mối quan hệ bất ngờ với những người xung quanh. Fredrik Backman kể lại quá khứ và hiện tại đan xen để hé lộ lý do đằng sau tính cách khó gần của Ove, ca ngợi tình người và sự chữa lành qua kết nối cộng đồng."],
    ],
  },
{
    t: "II. Thường thức",
    n: 57,
    sub: [
      {
        t: "Kinh tế",
        items: [
          ["Ứng Xử Với Trung Quốc", "Henry M. Paulson Jr.", undefined, "Cuốn sách là hồi ký của cựu Bộ trưởng Tài chính Mỹ Henry Paulson, ghi lại hàng chục năm ông tiếp xúc và đàm phán với giới lãnh đạo Trung Quốc trên cương vị lãnh đạo Goldman Sachs rồi Bộ Tài chính Hoa Kỳ. Tác phẩm phân tích quá trình cải cách kinh tế, sự trỗi dậy của Trung Quốc và cách nước này vận hành bộ máy chính trị, tài chính. Qua đó, tác giả đưa ra góc nhìn về quan hệ Mỹ - Trung và những thách thức trong việc ứng xử với một cường quốc đang lên."],
          ["Wealth, Poverty And Politics", "Thomas Sowell", undefined, "Cuốn sách phân tích các nguyên nhân dẫn đến chênh lệch giàu nghèo giữa các cá nhân, nhóm dân cư và quốc gia trên thế giới. Tác giả bác bỏ những lý giải đơn thuần dựa trên phân biệt đối xử hay bóc lột, thay vào đó nhấn mạnh vai trò của các yếu tố địa lý, văn hóa, xã hội và lịch sử. Sowell sử dụng số liệu và dẫn chứng thực nghiệm để lập luận rằng sự thịnh vượng không phân bổ đều là kết quả của nhiều nhân tố phức tạp hơn là ý chí chính trị đơn thuần."],
          ["Những Ông Trùm Tài Chính", "Liaquat Ahamed", undefined, "Cuốn sách từng đoạt giải Pulitzer kể về bốn thống đốc ngân hàng trung ương hàng đầu của Mỹ, Anh, Pháp và Đức trong giai đoạn giữa hai cuộc thế chiến. Tác giả phân tích các quyết định tiền tệ sai lầm của họ đã góp phần gây ra và kéo dài cuộc Đại suy thoái những năm 1930 như thế nào. Cuốn sách tái hiện bối cảnh chính trị - tài chính quốc tế đầy biến động của thời kỳ này qua góc nhìn của những người nắm giữ quyền lực kinh tế then chốt."],
          ["Lịch Sử Bí Mật Đế Chế Hoa Kỳ", "John Perkins", undefined, "Đây là phần tiếp theo của cuốn \"Lời Tự Thú Của Sát Thủ Kinh Tế\", trong đó John Perkins tiếp tục vạch trần các thủ đoạn ngầm mà giới tập đoàn và chính phủ Mỹ sử dụng để mở rộng ảnh hưởng kinh tế ra toàn cầu. Tác giả mô tả mạng lưới những \"sát thủ kinh tế\", nhà thầu quân sự và tổ chức tài chính quốc tế phối hợp thao túng các quốc gia đang phát triển. Cuốn sách đưa ra góc nhìn phê phán về cách thức vận hành của điều mà tác giả gọi là \"đế chế\" kinh tế ngầm của Hoa Kỳ."],
          ["Thế Giới Phẳng", "Thomas L. Friedman", undefined, "Cuốn sách phân tích quá trình toàn cầu hóa trong thế kỷ 21, khi các tiến bộ công nghệ và viễn thông đã \"làm phẳng\" sân chơi kinh tế toàn cầu. Friedman chỉ ra mười lực đẩy chính, từ sự sụp đổ của bức tường Berlin đến sự phát triển của Internet và chuỗi cung ứng toàn cầu, đã kết nối các cá nhân và doanh nghiệp trên khắp thế giới. Tác giả cũng bàn về những cơ hội và thách thức mà các quốc gia, doanh nghiệp và cá nhân phải đối mặt trong một thế giới ngày càng phẳng và cạnh tranh hơn."],
          ["Energy: A Human History", "Richard Rhodes", undefined, "Cuốn sách kể lại lịch sử loài người khai thác và sử dụng năng lượng, từ củi, than đá cho đến dầu mỏ, điện và năng lượng hạt nhân. Richard Rhodes khắc họa chân dung những nhà phát minh, kỹ sư và doanh nhân đã tạo ra các bước ngoặt công nghệ năng lượng qua từng thời kỳ. Tác phẩm cho thấy mối liên hệ chặt chẽ giữa các cuộc cách mạng năng lượng với sự phát triển kinh tế, xã hội của nhân loại."],
          ["Chiến Tranh Tiền Tệ", "Song Hongbing", undefined, "Cuốn sách trình bày một góc nhìn về lịch sử tài chính - tiền tệ thế giới, xoay quanh vai trò của các gia tộc ngân hàng quốc tế như Rothschild trong việc chi phối hệ thống tiền tệ toàn cầu. Tác giả lập luận rằng nhiều biến động kinh tế, chiến tranh và khủng hoảng tài chính trong lịch sử hiện đại có liên hệ với các toan tính của giới tài phiệt ngân hàng. Đây là cuốn sách gây nhiều tranh cãi vì cách tiếp cận mang tính giả thuyết và diễn giải lại các sự kiện lịch sử tài chính theo hướng thuyết âm mưu."],
          ["Lời Tự Thú Của Sát Thủ Kinh Tế", "John Perkins", undefined, "Cuốn hồi ký kể lại quãng thời gian tác giả làm việc với vai trò một \"sát thủ kinh tế\", sử dụng các báo cáo dự báo kinh tế bị thổi phồng để thuyết phục các nước đang phát triển vay những khoản nợ khổng lồ. Perkins mô tả cách các khoản vay này phục vụ lợi ích của các tập đoàn và chính phủ Mỹ, đồng thời đẩy nhiều quốc gia vào vòng xoáy nợ nần và lệ thuộc. Cuốn sách hé lộ mặt trái của toàn cầu hóa kinh tế và vai trò của các định chế tài chính quốc tế trong quá trình này."],
          ["Kinh Tế Học Hài Hước", "Steven D. Levitt & Stephen J. Dubner", undefined, "Cuốn sách vận dụng công cụ phân tích kinh tế học để lý giải những hiện tượng xã hội tưởng chừng không liên quan đến kinh tế, như tội phạm, gian lận thi cử hay cách đặt tên con. Levitt và Dubner sử dụng dữ liệu thực nghiệm để đặt câu hỏi và thách thức những quan niệm thông thường về nguyên nhân - kết quả trong đời sống. Qua đó, cuốn sách cho thấy sức mạnh của tư duy kinh tế học khi được áp dụng vào các vấn đề phi truyền thống."],
          ["Chiếc Lexus Và Cây Ô Liu", "Thomas L. Friedman", undefined, "Cuốn sách phân tích quá trình toàn cầu hóa cuối thế kỷ 20 qua ẩn dụ giữa \"chiếc Lexus\" tượng trưng cho hiện đại hóa, công nghệ và thị trường, với \"cây ô liu\" tượng trưng cho bản sắc dân tộc, văn hóa và cội nguồn. Friedman khảo sát cách các quốc gia và cá nhân phải cân bằng giữa việc hội nhập kinh tế toàn cầu và gìn giữ bản sắc truyền thống. Tác phẩm được xem là một trong những cuốn sách nền tảng giúp phổ biến khái niệm toàn cầu hóa tới độc giả đại chúng."],
          ["Nhà Đầu Tư Thông Minh", "Benjamin Graham", undefined, "Đây là cuốn sách kinh điển về đầu tư giá trị, trình bày các nguyên tắc phân tích và lựa chọn cổ phiếu một cách thận trọng, an toàn. Graham giới thiệu khái niệm \"biên an toàn\" và hình tượng \"Ngài Thị Trường\" để giúp nhà đầu tư phân biệt giữa đầu tư và đầu cơ. Cuốn sách hướng dẫn độc giả xây dựng chiến lược đầu tư dài hạn dựa trên phân tích cơ bản thay vì chạy theo biến động ngắn hạn của thị trường."],
          ["Thế Giới Rộng Lớn Và Có Nhiều Việc Phải Làm", "Kim Woo-Choong", undefined, "Cuốn sách là hồi ký kết hợp triết lý sống của Kim Woo-Choong, người sáng lập tập đoàn Daewoo, kể lại hành trình khởi nghiệp và xây dựng doanh nghiệp từ hai bàn tay trắng thành một trong những tập đoàn lớn nhất Hàn Quốc. Tác giả chia sẻ quan điểm về tinh thần dấn thân, dám nghĩ dám làm và không ngừng vươn ra thế giới để tìm kiếm cơ hội. Cuốn sách từng có ảnh hưởng lớn đến nhiều thế hệ thanh niên Hàn Quốc như một lời khích lệ về khát vọng và ý chí lập nghiệp."],
          ["Thịnh Vượng Tài Chính Tuổi 30", "Go Deuk Seong"],
          ["Tiền Không Mua Được Gì?", "Michael J. Sandel", undefined, "Cuốn sách của triết gia Michael Sandel đặt câu hỏi về giới hạn đạo đức của thị trường trong đời sống hiện đại, khi ngày càng nhiều lĩnh vực như giáo dục, y tế, quan hệ con người bị chi phối bởi logic mua bán. Tác giả đưa ra hàng loạt ví dụ thực tế cho thấy việc gắn giá tiền cho mọi thứ có thể làm biến chất giá trị vốn có của chúng. Sandel lập luận rằng xã hội cần thảo luận công khai về việc nơi nào thị trường nên và không nên có mặt."],
          ["Đừng Bao Giờ Đi Ăn Một Mình", "Keith Ferrazzi", undefined, "Cuốn sách trình bày các nguyên tắc và kỹ năng xây dựng mạng lưới quan hệ trong công việc và cuộc sống. Ferrazzi nhấn mạnh rằng thành công đến từ việc chân thành kết nối, giúp đỡ người khác trước khi mong nhận lại lợi ích cho bản thân. Tác giả chia sẻ nhiều kinh nghiệm cá nhân và chiến lược cụ thể để xây dựng, duy trì các mối quan hệ có giá trị lâu dài."],
          ["Chiến Lược Đại Dương Xanh", "W. Chan Kim", undefined, "Cuốn sách giới thiệu chiến lược kinh doanh nhằm giúp doanh nghiệp tạo ra những thị trường mới chưa có cạnh tranh (\"đại dương xanh\") thay vì chen chân vào các thị trường hiện hữu đã bão hòa (\"đại dương đỏ\"). Các tác giả trình bày công cụ \"đổi mới giá trị\", giúp doanh nghiệp vừa giảm chi phí vừa gia tăng giá trị cho khách hàng cùng lúc. Cuốn sách sử dụng nhiều case study thực tế từ các ngành công nghiệp khác nhau để minh họa cách áp dụng chiến lược này."],
        ],
      },
      {
        t: "Vật lý",
        items: [
          ["Bản Thiết Kế Vĩ Đại", "Stephen Hawking", undefined, "Cuốn sách của Stephen Hawking và Leonard Mlodinow tìm cách trả lời các câu hỏi lớn về nguồn gốc vũ trụ dựa trên lý thuyết M, một dạng mở rộng của lý thuyết dây. Các tác giả trình bày khái niệm đa vũ trụ và cho rằng các định luật vật lý có thể tự giải thích sự hình thành vũ trụ mà không cần đến một đấng sáng tạo. Cuốn sách trình bày các khái niệm vật lý lý thuyết phức tạp theo cách dễ tiếp cận với độc giả phổ thông."],
          ["Các Thế Giới Song Song", "Michio Kaku", undefined, "Cuốn sách khám phá các lý thuyết về đa vũ trụ và những thế giới song song trong vật lý hiện đại. Michio Kaku trình bày các chủ đề vũ trụ học như vụ nổ lớn, lạm phát vũ trụ, lý thuyết dây và số phận cuối cùng của vũ trụ. Tác giả cũng bàn về khả năng tồn tại của các vũ trụ song song và ý nghĩa triết học của những giả thuyết này đối với vị trí của con người trong vũ trụ."],
          ["Thế Giới Lượng Tử Kỳ Bí", "Silvia Arroyo Camejo", undefined, "Cuốn sách là một dẫn nhập dễ hiểu về cơ học lượng tử, được viết bởi tác giả người Đức nhằm giúp độc giả không chuyên tiếp cận những khái niệm kỳ lạ của thế giới hạ nguyên tử. Tác phẩm giải thích các hiện tượng như chồng chập lượng tử, rối lượng tử mà hạn chế tối đa việc sử dụng công thức toán học phức tạp. Cuốn sách giúp người đọc hình dung được sự khác biệt căn bản giữa thế giới lượng tử và trực giác thông thường của con người."],
          ["Vũ Trụ Trong Vỏ Hạt Dẻ", "Stephen Hawking", undefined, "Đây là cuốn sách tiếp nối \"Lược Sử Thời Gian\", trong đó Stephen Hawking cập nhật và mở rộng các chủ đề về thuyết tương đối, cơ học lượng tử và nỗ lực tìm kiếm lý thuyết thống nhất trong vật lý. Cuốn sách trình bày các khái niệm như hố đen, chiều không gian bổ sung và lý thuyết dây với nhiều hình minh họa trực quan. Hawking hướng tới việc giúp độc giả phổ thông hình dung được những ý tưởng tiên tiến nhất của vật lý lý thuyết đương đại."],
          ["Lược Sử Thời Gian", "Stephen Hawking", undefined, "Cuốn sách phổ biến khoa học kinh điển trình bày các khái niệm vũ trụ học như vụ nổ lớn, hố đen và bản chất của không - thời gian theo cách dễ hiểu cho độc giả phổ thông. Hawking giải thích lịch sử phát triển các lý thuyết vật lý về vũ trụ, từ Newton, Einstein cho đến các nghiên cứu hiện đại. Cuốn sách cũng đề cập đến nỗ lực của giới vật lý trong việc tìm kiếm một lý thuyết thống nhất giải thích mọi hiện tượng của vũ trụ."],
        ],
      },
      {
        t: "Lịch sử, Địa lý",
        items: [
          ["Sapiens: Lược Sử Loài Người", "Yuval Noah Harari", undefined, "Cuốn sách trình bày lịch sử loài người từ thời kỳ đồ đá cho đến hiện tại, qua các cuộc cách mạng nhận thức, nông nghiệp và khoa học. Harari lập luận rằng khả năng tạo ra và tin vào những \"câu chuyện hư cấu\" chung như tôn giáo, quốc gia, tiền tệ đã giúp loài người hợp tác quy mô lớn và thống trị hành tinh. Cuốn sách cũng đặt ra những câu hỏi về tương lai của loài người trong bối cảnh công nghệ sinh học và trí tuệ nhân tạo phát triển."],
          ["Súng, Vi Trùng Và Thép", "Jared Diamond", undefined, "Cuốn sách đặt câu hỏi vì sao một số nền văn minh lại có thể chinh phục và thống trị những nền văn minh khác trong lịch sử nhân loại. Jared Diamond lập luận rằng các yếu tố địa lý và môi trường, như sự phân bố cây trồng, vật nuôi thuần hóa được và hướng trục lục địa, đóng vai trò quyết định hơn là sự khác biệt về chủng tộc hay văn hóa. Cuốn sách đưa ra một cách giải thích mang tính khoa học tự nhiên cho sự bất bình đẳng quyền lực giữa các xã hội loài người."],
          ["Lược Sử Vạn Vật", "Bill Bryson", undefined, "Cuốn sách tổng hợp kiến thức phổ thông về nhiều lĩnh vực khoa học như vật lý, hóa học, sinh học, địa chất và thiên văn học. Bill Bryson kể lại lịch sử các khám phá khoa học lớn cùng chân dung những nhà khoa học đứng sau chúng theo giọng văn dí dỏm, dễ hiểu. Cuốn sách giúp độc giả phổ thông hình dung được bức tranh tổng thể về vũ trụ, Trái Đất và sự sống theo góc nhìn khoa học hiện đại."],
          ["Lịch Sử Văn Minh Thế Giới", "Vũ Dương Ninh", undefined, "Đây là giáo trình lịch sử trình bày quá trình hình thành và phát triển của các nền văn minh lớn trên thế giới, từ văn minh cổ đại phương Đông, phương Tây cho đến thời kỳ cận - hiện đại. Sách hệ thống hóa những thành tựu về chính trị, kinh tế, văn hóa, tư tưởng của các nền văn minh qua từng giai đoạn lịch sử. Đây là tài liệu tham khảo phổ biến trong giảng dạy lịch sử thế giới tại các trường đại học Việt Nam."],
          ["Tôi, Tương Lai & Thế Giới", "Nguyễn Phi Vân"],
          ["Lịch Sử Trung Đông 2.000 Năm Trở Lại Đây", "Bernard Lewis", undefined, "Cuốn sách trình bày lịch sử khu vực Trung Đông trải dài suốt hai nghìn năm, từ thời kỳ La Mã, sự trỗi dậy của đạo Hồi, đế chế Ottoman cho đến thời hiện đại. Bernard Lewis phân tích sự tương tác giữa các yếu tố chính trị, tôn giáo và văn hóa đã định hình khu vực này qua nhiều thế kỷ. Cuốn sách giúp độc giả hiểu được cội nguồn của nhiều xung đột và biến động chính trị đang diễn ra tại Trung Đông ngày nay."],
          ["The Silk Road", "Peter Frankopan", "Chưa đọc", "Cuốn sách viết lại lịch sử thế giới qua lăng kính Con đường Tơ lụa, coi khu vực trải dài từ Trung Đông đến Trung Á là trung tâm kết nối Đông - Tây của lịch sử nhân loại chứ không phải châu Âu như cách kể chuyện truyền thống. Peter Frankopan phân tích vai trò của các tuyến đường thương mại, tôn giáo và văn hóa đi qua khu vực này trong việc định hình các đế chế và nền văn minh lớn qua nhiều thế kỷ. Cuốn sách cũng liên hệ đến vị thế địa chính trị quan trọng của khu vực Con đường Tơ lụa trong bối cảnh thế giới đương đại."],
          ["Những Tù Nhân Của Địa Lý", "Tim Marshall", "Chưa đọc", "Cuốn sách phân tích cách các yếu tố địa lý như núi non, sông ngòi, đường biên giới tự nhiên chi phối chính sách đối ngoại và vận mệnh chính trị của các quốc gia. Tim Marshall khảo sát mười khu vực địa lý khác nhau trên thế giới, từ Nga, Trung Quốc đến Trung Đông và châu Phi, để giải thích các quyết định chiến lược của những cường quốc. Cuốn sách lập luận rằng dù công nghệ phát triển, các quốc gia vẫn bị ràng buộc, thậm chí trở thành \"tù nhân\", bởi chính điều kiện địa lý của mình."],
          ["Sử Việt, 12 Khúc Tráng Ca", "Dũng Phan", undefined, "Cuốn sách kể lại mười hai giai đoạn, sự kiện tiêu biểu trong lịch sử Việt Nam bằng lối viết gần gũi, giàu cảm xúc hướng đến độc giả đại chúng. Tác giả tái hiện lại các cuộc kháng chiến, triều đại và nhân vật lịch sử quan trọng đã góp phần hình thành nên tiến trình lịch sử dân tộc. Cuốn sách hướng đến việc khơi gợi niềm yêu thích tìm hiểu lịch sử Việt Nam cho thế hệ trẻ."],
        ],
      },
      {
        t: "Sinh học",
        items: [
          ["Dòng Sông Trôi Khuất Địa Đàng", "Richard Dawkins", undefined, "Cuốn sách sử dụng hình ảnh ẩn dụ về những \"dòng sông gen\" để giải thích quá trình tiến hóa của sự sống qua chọn lọc tự nhiên. Richard Dawkins trình bày quan điểm coi gen là đơn vị cơ bản của tiến hóa, thứ được truyền qua các thế hệ và định hình nên sự đa dạng sinh học. Cuốn sách giúp độc giả phổ thông hiểu sâu hơn về cơ chế di truyền và tiến hóa dưới góc nhìn sinh học hiện đại."],
          ["Đời Sống Bí Ẩn Của Cây", "Peter Wohlleben", undefined, "Cuốn sách khám phá đời sống của cây rừng, cho thấy cây có khả năng giao tiếp, hỗ trợ lẫn nhau qua mạng lưới rễ và nấm cộng sinh trong lòng đất. Peter Wohlleben, một nhà lâm học người Đức, trình bày các nghiên cứu và quan sát cho thấy cây có những hành vi phức tạp như cảnh báo nguy hiểm, chia sẻ dinh dưỡng cho cây khác. Cuốn sách thay đổi cách nhìn của độc giả về thế giới thực vật, vốn trước đây thường bị xem là thụ động và vô tri."],
          ["Nguồn Gốc Các Loài", "Charles Darwin", undefined, "Đây là tác phẩm khoa học nền tảng trình bày thuyết tiến hóa bằng chọn lọc tự nhiên của Charles Darwin. Cuốn sách giải thích cách các loài sinh vật biến đổi theo thời gian thông qua biến dị di truyền và quá trình chọn lọc dựa trên khả năng sinh tồn, sinh sản. Tác phẩm đã đặt nền móng cho toàn bộ ngành sinh học tiến hóa hiện đại và làm thay đổi căn bản nhận thức của nhân loại về nguồn gốc sự sống."],
          ["Về Bản Tính Người", "Edward O. Wilson", undefined, "Cuốn sách vận dụng khung lý thuyết xã hội sinh học để lý giải nguồn gốc sinh học của các hành vi con người như hung hăng, tình dục, lòng vị tha và tôn giáo. Edward O. Wilson lập luận rằng nhiều đặc điểm hành vi và xã hội của con người có cội rễ từ quá trình tiến hóa sinh học chứ không chỉ đơn thuần do văn hóa quyết định. Cuốn sách từng gây nhiều tranh luận học thuật vì cách tiếp cận táo bạo khi áp dụng sinh học vào giải thích bản chất con người."],
        ],
      },
      {
        t: "Công nghệ",
        items: [
          ["Permanent Record", "Edward Snowden", "Chưa đọc", "Cuốn hồi ký kể lại cuộc đời của Edward Snowden, từ khi làm việc cho Cơ quan An ninh Quốc gia Mỹ (NSA) và Cục Tình báo Trung ương (CIA) cho đến quyết định công khai các chương trình giám sát hàng loạt bí mật của chính phủ Mỹ. Snowden mô tả chi tiết động cơ, quá trình thu thập và tiết lộ các tài liệu mật cho báo giới vào năm 2013, cũng như hậu quả pháp lý và cá nhân mà ông phải đối mặt sau đó. Cuốn sách đặt ra những câu hỏi về ranh giới giữa an ninh quốc gia, quyền riêng tư cá nhân và tự do trong thời đại giám sát số."],
          ["The Big Nine", "Amy Webb", undefined, "Cuốn sách phân tích vai trò của chín tập đoàn công nghệ lớn nhất, gồm sáu công ty Mỹ (Google, Microsoft, Amazon, Facebook, IBM, Apple) và ba công ty Trung Quốc (Baidu, Alibaba, Tencent), trong việc định hình sự phát triển của trí tuệ nhân tạo toàn cầu. Amy Webb cảnh báo về những rủi ro khi tương lai của AI bị chi phối bởi lợi ích thương mại và chính trị của một số ít tổ chức. Tác giả đề xuất các giải pháp nhằm đảm bảo AI phát triển theo hướng có lợi và an toàn hơn cho nhân loại."],
          ["Công Nghệ Blockchain", "Don Tapscott", undefined, "Cuốn sách giới thiệu công nghệ blockchain vượt ra ngoài phạm vi tiền điện tử, giải thích cách thức hoạt động của sổ cái phân tán và tính năng bảo mật, minh bạch của nó. Don Tapscott phân tích những ứng dụng tiềm năng của blockchain trong các lĩnh vực như tài chính, chuỗi cung ứng, quản trị và sở hữu tài sản. Tác giả lập luận rằng blockchain có thể tạo ra một cuộc cách mạng thay đổi sâu sắc cách thức vận hành của nền kinh tế toàn cầu."],
        ],
      },
      {
        t: "Đời sống / Khác",
        items: [
          ["Năng Lượng Sống Từ Thảo Dược", "Rosalee De La Forêt", undefined, "Cuốn sách giới thiệu về công dụng chữa bệnh và bồi bổ sức khỏe của các loại thảo dược, gia vị quen thuộc thường có sẵn trong gian bếp. Rosalee De La Forêt, một chuyên gia thảo dược học, hướng dẫn độc giả cách sử dụng các loại thảo mộc này để hỗ trợ điều trị những vấn đề sức khỏe thường gặp. Cuốn sách kết hợp giữa kiến thức y học cổ truyền và những nghiên cứu khoa học hiện đại về thảo dược."],
          ["Nhân Tố Enzyme", "Hiromi Shinya", undefined, "Cuốn sách trình bày quan điểm của bác sĩ Hiromi Shinya về vai trò của enzyme diệu kỳ trong cơ thể đối với sức khỏe con người. Dựa trên kinh nghiệm nhiều năm nội soi đường tiêu hóa cho bệnh nhân, tác giả đưa ra các khuyến nghị về chế độ ăn uống nhằm bảo tồn enzyme và phòng ngừa bệnh tật. Cuốn sách nhấn mạnh mối liên hệ giữa thói quen ăn uống, lối sống với sức khỏe đường ruột và tuổi thọ."],
          ["Ăn Sao Không Chết", "Michael Greger", undefined, "Cuốn sách phân tích vai trò của chế độ dinh dưỡng trong việc phòng ngừa và hỗ trợ điều trị những nguyên nhân gây tử vong hàng đầu như bệnh tim mạch, ung thư, tiểu đường. Michael Greger tổng hợp các nghiên cứu khoa học để đưa ra khuyến nghị về một chế độ ăn thiên về thực vật nhằm cải thiện sức khỏe tổng thể. Tác giả đề xuất khung \"Daily Dozen\" gồm những nhóm thực phẩm nên bổ sung hằng ngày để tối ưu hóa sức khỏe."],
          ["Ăn Gì Cho Không Độc Hại", "Pha Lê"],
          ["Chào Juice", "Trần Thanh Huyền"],
          ["Ý Tưởng Này Là Của Chúng Mình", "Huỳnh Vĩnh Sơn", undefined, "Cuốn sách chia sẻ kinh nghiệm và phương pháp phát triển ý tưởng sáng tạo trong lĩnh vực quảng cáo, được đúc kết từ quá trình làm nghề copywriter của tác giả Huỳnh Vĩnh Sơn. Sách trình bày các bước tư duy, kỹ thuật khơi nguồn cảm hứng và cách biến những ý tưởng ban đầu thành các chiến dịch quảng cáo sáng tạo, hiệu quả. Tác giả cũng chia sẻ nhiều câu chuyện, ví dụ thực tế từ ngành quảng cáo Việt Nam để minh họa cho quá trình sáng tạo nội dung."],
          ["Thing Explainer", "Randall Munroe", undefined, "Cuốn sách giải thích các khái niệm và sự vật phức tạp như lò phản ứng hạt nhân, tế bào, tên lửa bằng cách chỉ sử dụng một nghìn từ tiếng Anh thông dụng nhất. Randall Munroe, tác giả loạt truyện tranh khoa học xkcd, kết hợp lối diễn giải hài hước với các sơ đồ minh họa đơn giản, trực quan. Cuốn sách mang đến cách tiếp cận mới mẻ, dễ hiểu cho những chủ đề khoa học kỹ thuật vốn thường bị coi là khô khan."],
          ["Cãi Gì Cũng Thắng", "Madsen Pirie", undefined, "Cuốn sách hệ thống hóa các loại ngụy biện (fallacy) thường gặp trong tranh luận, lý giải cấu trúc và cách thức mà chúng đánh lừa lập luận logic. Madsen Pirie phân tích từng loại ngụy biện bằng ví dụ cụ thể, giúp độc giả nhận diện được các thủ thuật lập luận sai lệch mà người khác có thể sử dụng. Cuốn sách vừa là công cụ giúp người đọc tranh luận thuyết phục hơn, vừa là lời cảnh báo về việc lạm dụng ngụy biện trong giao tiếp."],
          ["Viết Gì Cũng Đúng", "Anthony Weston", undefined, "Cuốn sách hướng dẫn cách xây dựng một lập luận rõ ràng, chặt chẽ và có tính thuyết phục trong văn bản viết. Anthony Weston trình bày các quy tắc cụ thể về việc sử dụng bằng chứng, ví dụ và suy luận logic để bảo vệ một luận điểm. Cuốn sách được xem là cẩm nang súc tích, hữu ích cho những ai muốn cải thiện kỹ năng viết luận và tư duy phản biện."],
          ["Phi Lý Trí", "Dan Ariely", undefined, "Cuốn sách thuộc lĩnh vực kinh tế học hành vi, trình bày hàng loạt thí nghiệm cho thấy con người thường đưa ra quyết định một cách phi lý trí nhưng theo những khuôn mẫu có thể dự đoán được. Dan Ariely phân tích các yếu tố tâm lý như hiệu ứng mỏ neo, cảm giác sở hữu hay ảnh hưởng xã hội tác động đến hành vi tiêu dùng và ra quyết định của con người. Cuốn sách thách thức giả định truyền thống trong kinh tế học cổ điển rằng con người luôn hành động một cách duy lý."],
          ["Tư Duy Nhanh Và Chậm", "Daniel Kahneman", undefined, "Cuốn sách trình bày hai hệ thống tư duy của con người: Hệ thống 1 vận hành nhanh, trực giác và cảm tính; Hệ thống 2 vận hành chậm, có chủ đích và dựa trên lý trí. Daniel Kahneman, người đoạt giải Nobel Kinh tế, phân tích các thiên kiến nhận thức và lối tắt tư duy khiến con người thường xuyên đưa ra những phán đoán, quyết định sai lầm. Cuốn sách có ảnh hưởng sâu rộng đến các lĩnh vực kinh tế học hành vi, tâm lý học và khoa học ra quyết định."],
          ["Điểm Bùng Phát", "Malcolm Gladwell", undefined, "Cuốn sách phân tích cách các ý tưởng, xu hướng và hành vi xã hội có thể lan truyền nhanh chóng giống như một dịch bệnh cho đến khi đạt \"điểm bùng phát\". Malcolm Gladwell giới thiệu các yếu tố then chốt như quy luật thiểu số đặc biệt, yếu tố kết dính của thông điệp và sức mạnh của bối cảnh trong việc tạo ra những thay đổi xã hội quy mô lớn. Cuốn sách sử dụng nhiều ví dụ thực tế từ kinh doanh, dịch tễ học và văn hóa đại chúng để minh họa cho các luận điểm này."],
          ["Chờ Đến Mẫu Giáo Thì Đã Muộn", "Masaru Ibuka", undefined, "Cuốn sách trình bày quan điểm giáo dục sớm cho trẻ, cho rằng những năm đầu đời, đặc biệt trước ba tuổi, là giai đoạn then chốt quyết định sự phát triển trí não của trẻ. Masaru Ibuka, đồng sáng lập tập đoàn Sony, lập luận rằng việc chờ đến tuổi mẫu giáo mới bắt đầu giáo dục trẻ là quá muộn để tận dụng tối đa tiềm năng phát triển não bộ. Cuốn sách đưa ra các gợi ý về phương pháp kích thích, nuôi dưỡng trẻ nhỏ trong giai đoạn đầu đời."],
          ["Cuốn Sách Hoàn Hảo Về Ngôn Ngữ Cơ Thể", "Allan Pease", undefined, "Cuốn sách hướng dẫn cách quan sát và giải mã ngôn ngữ cơ thể của người đối diện trong giao tiếp hằng ngày. Allan Pease phân tích ý nghĩa của các cử chỉ, tư thế, biểu cảm khuôn mặt phổ biến trong nhiều tình huống xã hội khác nhau. Cuốn sách giúp độc giả cải thiện khả năng đọc hiểu tín hiệu phi ngôn từ để giao tiếp hiệu quả hơn."],
          ["Bạn Không Thông Minh Lắm Đâu", "David McRaney", undefined, "Cuốn sách khám phá những ảo tưởng và thiên kiến nhận thức phổ biến mà con người thường có về chính bản thân mình. David McRaney trình bày các nghiên cứu tâm lý học để giải thích vì sao con người dễ đánh giá sai về trí nhớ, động cơ và khả năng ra quyết định của chính mình. Cuốn sách giúp độc giả nhận diện rõ hơn những giới hạn trong tư duy của bản thân để tránh mắc phải các sai lầm nhận thức thường gặp."],
          ["Dám Bị Ghét", "Fumitake Koga", undefined, "Cuốn sách được viết dưới dạng đối thoại giữa một triết gia và một thanh niên, giới thiệu tư tưởng tâm lý học của Alfred Adler đến độc giả đại chúng. Sách lập luận rằng con người có thể đạt được tự do và hạnh phúc thực sự khi dám chấp nhận bị người khác không hài lòng hay ghét bỏ, thay vì sống theo kỳ vọng của người khác. Tác phẩm khuyến khích độc giả tách bạch nhiệm vụ của bản thân với nhiệm vụ của người khác để sống một cuộc đời tự chủ hơn."],
          ["Scrum Và XP Từ Các Chiến Hào", "Henrik Kniberg", undefined, "Cuốn sách là cẩm nang thực hành về việc áp dụng các phương pháp phát triển phần mềm linh hoạt Scrum và Extreme Programming (XP) vào công việc thực tế của các nhóm phát triển. Henrik Kniberg chia sẻ kinh nghiệm trực tiếp từ các dự án mà ông từng tham gia, đưa ra những giải pháp cụ thể cho các vấn đề thường gặp khi triển khai Agile. Cuốn sách được đánh giá là tài liệu ngắn gọn, súc tích và thực tiễn dành cho các nhóm phát triển phần mềm mới bắt đầu áp dụng Agile."],
          ["Don't Make Me Think", "Steve Krug", undefined, "Cuốn sách trình bày các nguyên tắc cơ bản về thiết kế trải nghiệm người dùng (UX) cho website và ứng dụng, với nguyên lý cốt lõi là một giao diện tốt phải trực quan, dễ hiểu ngay từ cái nhìn đầu tiên. Steve Krug đưa ra các hướng dẫn thực tế, dễ áp dụng để cải thiện khả năng sử dụng của sản phẩm số. Cuốn sách được xem là một trong những tài liệu kinh điển, dễ tiếp cận nhất về lĩnh vực thiết kế usability."],
          ["Ngôn Ngữ Cơ Thể", "Allan & Barbara Pease", undefined, "Cuốn sách giải thích ý nghĩa của các cử chỉ, điệu bộ và biểu cảm cơ thể thường gặp trong giao tiếp giữa người với người. Allan và Barbara Pease trình bày các nghiên cứu về ngôn ngữ hình thể, chỉ ra cách những tín hiệu phi ngôn từ này thường bộc lộ cảm xúc và suy nghĩ thật của con người. Cuốn sách hướng dẫn độc giả cách quan sát và vận dụng ngôn ngữ cơ thể để giao tiếp thuyết phục và hiệu quả hơn."],
          ["100 Kĩ Năng Sinh Tồn", "Clint Emerson", undefined, "Cuốn sách tổng hợp các kỹ năng sinh tồn và tự vệ được đúc kết từ kinh nghiệm huấn luyện của lực lượng đặc nhiệm. Clint Emerson, một cựu biệt kích hải quân Mỹ (SEAL), trình bày các kỹ thuật thực tế để đối phó với những tình huống nguy hiểm như thoát hiểm, ứng phó khẩn cấp hay tự vệ. Cuốn sách hướng đến việc trang bị cho độc giả phổ thông những kỹ năng cơ bản để tăng khả năng sống sót trong các tình huống bất trắc."],
        ],
      },
      {
        t: "Văn học",
        items: [["The Story Of English / Language Story", "David Crystal", undefined, "Cuốn sách kể lại lịch sử hình thành và phát triển của tiếng Anh, từ nguồn gốc là một ngôn ngữ German nhỏ bé cho đến khi trở thành ngôn ngữ toàn cầu ngày nay. David Crystal, một nhà ngôn ngữ học nổi tiếng, phân tích quá trình biến đổi của tiếng Anh qua các thời kỳ lịch sử cùng với sự đa dạng của các phương ngữ, biến thể trên khắp thế giới. Cuốn sách giúp độc giả hiểu rõ hơn về mối quan hệ giữa ngôn ngữ, lịch sử và văn hóa trong sự phát triển của tiếng Anh."]],
      },
    ],
  },
{
    t: "III. Du ký",
    n: 13,
    items: [
      ["Mật Mã Tây Tạng", "Hà Mã", undefined, "Mật Mã Tây Tạng là bộ tiểu thuyết phiêu lưu nhiều tập của nhà văn Trung Quốc Hà Mã, lấy bối cảnh vùng đất Tây Tạng huyền bí. Câu chuyện theo chân một nhóm nhà thám hiểm trên hành trình truy tìm một loài ong khổng lồ và giải mã những bí ẩn cổ xưa gắn liền với văn hóa, tôn giáo Tây Tạng. Tác phẩm kết hợp yếu tố phiêu lưu, kỳ bí và kiến thức về địa lý, lịch sử vùng cao nguyên này."],
      ["Chân Đi Không Mỏi", "Hằng Đinh", undefined, "Chân Đi Không Mỏi là cuốn sách du ký của tác giả Đinh Hằng, ghi lại hành trình một mình khám phá nhiều quốc gia trên thế giới. Cuốn sách chia sẻ những trải nghiệm, khó khăn và bài học rút ra từ lối du lịch bụi, tiết kiệm chi phí. Qua đó, tác giả truyền tải tinh thần dấn thân, chủ động khám phá thế giới của người trẻ."],
      ["Từ Rừng Thẳm Amazon Đến Quê Hương Bolero", "Nguyễn Tập"],
      ["Mekong - Phù Sa Phiêu Bạt", "Khải Đơn", undefined, "Mekong - Phù Sa Phiêu Bạt là tác phẩm bút ký của nhà văn Khải Đơn, viết về hành trình dọc theo dòng sông Mekong qua nhiều quốc gia Đông Nam Á. Cuốn sách khắc họa đời sống, văn hóa và số phận con người gắn bó với dòng sông này. Tác giả kết hợp quan sát thực địa với suy ngẫm về những biến đổi môi trường và xã hội dọc lưu vực Mekong."],
      ["Tiếng Gọi Nơi Hoang Dã", "Jack London", undefined, "Tiếng Gọi Nơi Hoang Dã kể về Buck, một chú chó nhà bị bắt cóc và bán làm chó kéo xe trong thời kỳ đổ xô tìm vàng ở Klondike. Qua quá trình sinh tồn khắc nghiệt giữa vùng đất hoang dã phương Bắc, Buck dần đánh thức bản năng hoang dã của tổ tiên trong mình. Tác phẩm của Jack London khám phá ranh giới giữa văn minh và bản năng nguyên thủy trong thế giới tự nhiên khắc nghiệt."],
      ["Cuộc Đời Của Pi", "Yann Martel", undefined, "Cuộc Đời Của Pi kể về Piscine Molitor Patel, một cậu bé Ấn Độ sống sót sau vụ đắm tàu và trôi dạt trên biển suốt hơn hai trăm ngày cùng một con hổ Bengal tên Richard Parker. Cuốn tiểu thuyết đan xen giữa hiện thực sinh tồn khắc nghiệt và những suy tưởng về tôn giáo, niềm tin và bản chất của sự thật. Yann Martel đặt ra câu hỏi về ranh giới giữa câu chuyện và hiện thực, giữa lý trí và đức tin."],
      ["Dế Mèn Phiêu Lưu Ký", "Tô Hoài", undefined, "Dế Mèn Phiêu Lưu Ký kể về hành trình phiêu lưu của chú dế tên Dế Mèn qua thế giới loài vật nhỏ bé. Từ một chú dế kiêu ngạo, bồng bột, Dế Mèn dần trưởng thành qua những va vấp, sai lầm và các cuộc gặp gỡ với nhiều nhân vật khác nhau. Tác phẩm của Tô Hoài truyền tải bài học về lòng dũng cảm, tình bạn và trách nhiệm với cộng đồng."],
      ["Gulliver Du Ký", "Jonathan Swift", undefined, "Gulliver Du Ký kể về những chuyến hải hành kỳ lạ của bác sĩ Lemuel Gulliver đến các vùng đất tưởng tượng như xứ sở người tí hon Lilliput và xứ sở người khổng lồ Brobdingnag. Qua những trải nghiệm ở các thế giới khác thường này, tác phẩm châm biếm sâu cay chính trị, xã hội và bản chất con người thời bấy giờ. Jonathan Swift sử dụng yếu tố hư cấu, phóng đại để phản ánh những thói hư tật xấu của xã hội Anh thế kỷ 18."],
      ["Hai Vạn Dặm Dưới Đáy Biển", "Jules Verne", undefined, "Hai Vạn Dặm Dưới Đáy Biển kể về hành trình khám phá đại dương của giáo sư Pierre Aronnax cùng các cộng sự trên con tàu ngầm Nautilus của thuyền trưởng Nemo bí ẩn. Cuốn tiểu thuyết khoa học viễn tưởng đưa người đọc qua nhiều vùng biển kỳ thú với các loài sinh vật biển và cảnh quan dưới đáy đại dương. Jules Verne kết hợp trí tưởng tượng khoa học với những dự đoán vượt thời đại về công nghệ tàu ngầm."],
      ["Kỳ Bí Dòng Sông Sôi Trong Lòng Amazon", "Andrés Ruzo", undefined, "Kỳ Bí Dòng Sông Sôi Trong Lòng Amazon kể về hành trình của nhà địa nhiệt học Andrés Ruzo đi tìm hiểu về một con sông sôi có thật trong rừng mưa Amazon ở Peru. Cuốn sách kết hợp giữa nghiên cứu khoa học địa chất, truyền thuyết bản địa và nỗ lực bảo tồn khu vực tự nhiên đặc biệt này trước nguy cơ bị khai thác. Tác giả chia sẻ cả hành trình khoa học lẫn trải nghiệm cá nhân trong quá trình khám phá hiện tượng thiên nhiên hiếm có này."],
      ["Đột Nhiên Đến Tây Tạng", "Trần Khôn"],
      ["Bước Chân Việt Nam - 4 Cực 1 Đỉnh", "Ngô Huy Hòa"],
      ["Nhắm Mắt Thấy Paris", "Dương Thụy"],
    ],
  },
  {
    t: "IV. Triết",
    n: 15,
    items: [
      ["Tự Do Đầu Tiên Và Cuối Cùng", "Jiddu Krishnamurti", undefined, "Tự Do Đầu Tiên Và Cuối Cùng tập hợp các bài giảng và đối thoại của Jiddu Krishnamurti về bản chất của tự do, tư duy và sự giác ngộ. Tác giả cho rằng tự do đích thực không đến từ việc thay đổi hoàn cảnh bên ngoài mà từ việc con người hiểu rõ chính tâm trí và những điều kiện hóa của bản thân. Cuốn sách khuyến khích người đọc quan sát trực tiếp thực tại, thoát khỏi sự lệ thuộc vào quyền uy, tín điều và khuôn mẫu tư tưởng có sẵn."],
      ["Suy Nghĩ Vẩn Vơ Của Kẻ Nhàn Rỗi", "Jerome K. Jerome", undefined, "Suy Nghĩ Vẩn Vơ Của Kẻ Nhàn Rỗi là tập tiểu luận hài hước của Jerome K. Jerome, bàn về những chủ đề đời thường như tình yêu, sự lười biếng, ký ức hay các mối quan hệ. Tác giả sử dụng giọng văn dí dỏm, tự trào để nhìn nhận những khía cạnh nhỏ nhặt nhưng thú vị của cuộc sống thường nhật. Cuốn sách phản ánh tinh thần hài hước đặc trưng của văn học Anh cuối thế kỷ 19."],
      ["Nỗi Lo Âu Về Địa Vị", "Alain de Botton", undefined, "Nỗi Lo Âu Về Địa Vị của Alain de Botton phân tích nguyên nhân khiến con người hiện đại luôn lo lắng về vị trí, danh tiếng và sự công nhận của xã hội. Tác giả chỉ ra những yếu tố lịch sử, kinh tế và văn hóa đã làm gia tăng tâm lý so sánh và bất an về địa vị trong xã hội hiện đại. Cuốn sách cũng đề xuất một số cách tiếp cận triết học, nghệ thuật và tôn giáo giúp con người giảm bớt sự lệ thuộc vào đánh giá của người khác."],
      ["Luận Về Yêu", "Alain de Botton", undefined, "Luận Về Yêu kể lại một câu chuyện tình yêu từ khi gặp gỡ, yêu say đắm cho đến khi tan vỡ, qua đó Alain de Botton lồng ghép những suy ngẫm triết học về bản chất của tình yêu. Tác giả phân tích tâm lý, sự hoài nghi và các giai đoạn cảm xúc mà một mối quan hệ lãng mạn thường trải qua. Cuốn sách kết hợp giữa tự sự và triết lý, mang đến cái nhìn vừa cảm xúc vừa lý trí về tình yêu."],
      ["Suy Tưởng", "Marcus Aurelius", undefined, "Suy Tưởng là tập hợp những ghi chép cá nhân của hoàng đế La Mã Marcus Aurelius, viết cho chính mình theo tinh thần triết học Khắc kỷ. Tác phẩm bàn về đức hạnh, lý trí, sự chấp nhận số phận và cách sống hài hòa với tự nhiên. Những suy tưởng này thể hiện nỗ lực tự rèn luyện đạo đức và giữ vững sự bình thản trước nghịch cảnh của một nhà lãnh đạo."],
      ["Trò Chuyện Với Vĩ Nhân", "Osho"],
      ["Plato Và Con Thú Mỏ Vịt Bước Vào Quán Bar", "Thomas Cathcart", undefined, "Plato Và Con Thú Mỏ Vịt Bước Vào Quán Bar sử dụng các câu chuyện cười và giai thoại hài hước để giải thích những khái niệm triết học phức tạp một cách dễ hiểu. Hai tác giả Thomas Cathcart và Daniel Klein dẫn dắt người đọc qua các chủ đề như siêu hình học, đạo đức học, tôn giáo và logic thông qua lăng kính hài hước. Cuốn sách nhằm mục đích phổ biến triết học đến độc giả phổ thông theo cách gần gũi, sinh động."],
      ["Đạo Đức Kinh", "Lão Tử", undefined, "Đạo Đức Kinh là tác phẩm kinh điển của Lão Tử, nền tảng của triết học Đạo giáo Trung Hoa cổ đại. Cuốn sách trình bày khái niệm về Đạo - quy luật vận hành tự nhiên của vũ trụ - và Đức, cách con người sống hài hòa thuận theo Đạo. Tác phẩm đề cao lối sống vô vi, giản dị, khiêm nhường và không cưỡng cầu."],
      ["Lĩnh Nam Chích Quái", "Trần Thế Pháp", undefined, "Lĩnh Nam Chích Quái là tập hợp các truyền thuyết, thần thoại dân gian cổ của Việt Nam do Trần Thế Pháp biên soạn vào thời Trần. Tác phẩm ghi lại nhiều câu chuyện về nguồn gốc dân tộc như truyền thuyết Lạc Long Quân - Âu Cơ, Thánh Gióng, Sơn Tinh - Thủy Tinh cùng nhiều nhân vật, sự tích kỳ lạ khác. Cuốn sách là một trong những nguồn tư liệu quan trọng phản ánh tín ngưỡng, văn hóa và lịch sử buổi đầu dựng nước của người Việt."],
      ["Sổ Tay Nhà Thôi Miên", "Cao Minh"],
      ["Thiên Tài Bên Trái, Kẻ Điên Bên Phải", "Ming Gao", undefined, "Thiên Tài Bên Trái, Kẻ Điên Bên Phải là tập hợp những cuộc trò chuyện của tác giả với nhiều bệnh nhân tâm thần và những người có tư duy khác biệt. Qua các cuộc đối thoại này, cuốn sách hé lộ những góc nhìn kỳ lạ, độc đáo về thế giới, khoa học, tôn giáo và bản chất thực tại từ góc độ của những người bị coi là \"điên\". Tác phẩm đặt ra câu hỏi về ranh giới mong manh giữa thiên tài và bệnh tâm thần, giữa chuẩn mực và khác biệt."],
      ["Thiền: Tự Do Đầu Tiên Và Cuối Cùng", "Osho"],
      ["The Daily Stoic", "Ryan Holiday", undefined, "The Daily Stoic tập hợp 366 đoạn suy ngẫm ngắn, mỗi ngày một bài, được Ryan Holiday biên soạn dựa trên tư tưởng của các triết gia Khắc kỷ như Marcus Aurelius, Seneca và Epictetus. Mỗi bài viết kèm theo phần diễn giải giúp người đọc áp dụng triết lý Khắc kỷ vào các tình huống đời sống hiện đại. Cuốn sách hướng đến việc rèn luyện sự bình thản, kỷ luật và trí tuệ thông qua thực hành hàng ngày."],
      ["The Myth Of Sisyphus", "Albert Camus", undefined, "The Myth Of Sisyphus là tiểu luận triết học của Albert Camus, bàn về khái niệm phi lý trong sự tồn tại của con người. Camus phân tích mâu thuẫn giữa khát khao tìm kiếm ý nghĩa của con người và sự im lặng, vô nghĩa của vũ trụ. Tác giả mượn hình tượng thần thoại Sisyphus bị đày vĩnh viễn đẩy tảng đá lên núi để minh họa cho việc con người vẫn có thể tìm thấy hạnh phúc ngay trong sự phi lý của cuộc sống."],
      ["Love", "Osho", undefined, "Love tập hợp các bài giảng của Osho về bản chất của tình yêu và các hình thái khác nhau của nó trong đời sống con người. Osho phân biệt giữa tình yêu mang tính chiếm hữu, lệ thuộc với một dạng tình yêu tự do, không ràng buộc mà ông cho là đích thực. Tác phẩm khuyến khích người đọc chuyển hóa nhận thức về yêu thương, hướng tới trạng thái yêu thương xuất phát từ sự trọn vẹn nội tâm hơn là nhu cầu thiếu thốn."],
    ],
  },
  {
    t: "V. Tiểu sử",
    n: 6,
    items: [
      ["Angelina Jolie - Bản Sắc Một Huyền Thoại", "Kay", undefined, "Angelina Jolie - Bản Sắc Một Huyền Thoại kể lại cuộc đời và sự nghiệp của nữ diễn viên, đạo diễn Angelina Jolie, từ những ngày đầu bước chân vào điện ảnh Hollywood đến khi trở thành một trong những ngôi sao có sức ảnh hưởng lớn nhất thế giới. Cuốn sách đề cập đến hành trình sự nghiệp diễn xuất với nhiều vai diễn ấn tượng cùng những hoạt động thiện nguyện, nhân đạo của cô với vai trò đại sứ thiện chí của Liên Hợp Quốc. Tác phẩm khắc họa hình ảnh một người phụ nữ vừa thành công trong nghệ thuật vừa có nhiều đóng góp cho các vấn đề xã hội toàn cầu."],
      ["Anne Frank", "Alicja Kaczyńska", undefined, "Anne Frank kể lại cuộc đời của cô bé người Do Thái Anne Frank, người cùng gia đình phải trốn trong một căn gác bí mật tại Amsterdam trong thời gian Đức Quốc xã chiếm đóng Hà Lan. Trong thời gian ẩn náu, Anne đã viết nhật ký ghi lại những suy nghĩ, cảm xúc và nỗi sợ hãi của một thiếu nữ giữa chiến tranh. Sau khi Anne qua đời trong trại tập trung, cuốn nhật ký của cô được xuất bản và trở thành một trong những chứng tích quan trọng nhất về thảm họa diệt chủng Holocaust."],
      ["Bùi Kiến Thành - Người Mở Khóa Lãng Du", "Lê Xuân Khoa"],
      ["Madame Nhu - Quyền Lực Bà Rồng", "Monique Brinson Demery", undefined, "Madame Nhu - Quyền Lực Bà Rồng là cuốn tiểu sử về Trần Lệ Xuân, thường được biết đến với biệt danh Madame Nhu, người từng giữ vai trò đệ nhất phu nhân trên thực tế của chính quyền Việt Nam Cộng hòa dưới thời Ngô Đình Diệm. Tác giả Monique Brinson Demery dựa trên các cuộc phỏng vấn trực tiếp với bà trong những năm cuối đời cùng tài liệu lịch sử để tái hiện quá trình bà từ một thiếu nữ trở thành nhân vật quyền lực, gây tranh cãi trên chính trường miền Nam Việt Nam. Cuốn sách khắc họa sự thăng trầm quyền lực của bà, từ đỉnh cao ảnh hưởng chính trị đến cuộc sống lưu vong sau cuộc đảo chính năm 1963."],
      ["Nhật Ký Đặng Thùy Trâm", "Đặng Thùy Trâm", undefined, "Nhật Ký Đặng Thùy Trâm ghi lại những trang nhật ký của bác sĩ quân y Đặng Thùy Trâm trong thời gian bà công tác tại một bệnh xá dã chiến ở Quảng Ngãi trong chiến tranh Việt Nam. Cuốn nhật ký phản ánh chân thực cuộc sống, những khó khăn, mất mát và lý tưởng sống của một người thầy thuốc trẻ giữa bom đạn chiến trường. Sau khi được một cựu chiến binh Mỹ lưu giữ và trao trả nhiều năm sau chiến tranh, cuốn nhật ký đã được xuất bản và trở thành tác phẩm gây xúc động rộng rãi tại Việt Nam."],
      ["Bắt Đầu Từ Một Kết Thúc", "Lý Minh Tùng"],
    ],
  },
{
    t: "VI. Self-help",
    n: 14,
    items: [
      ["Happiness - A Philosopher's Guide", "Frédéric Lenoir", undefined, "Cuốn sách tổng hợp và phân tích quan niệm về hạnh phúc qua các trường phái triết học, tôn giáo và tư tưởng lớn từ cổ đại đến hiện đại, từ triết học Hy Lạp, Phật giáo cho đến các nghiên cứu tâm lý học đương đại. Tác giả Frédéric Lenoir xem xét những yếu tố cấu thành hạnh phúc như sự bằng lòng, tình yêu thương và ý nghĩa sống, đồng thời chỉ ra sự khác biệt giữa hạnh phúc và khoái lạc nhất thời. Qua đó, cuốn sách đưa ra một cái nhìn tổng quan giúp người đọc suy ngẫm về con đường riêng để đạt được hạnh phúc bền vững."],
      ["Hygge - The Danish Art Of Happiness", "Marie Tourell Søderberg", undefined, "Cuốn sách giới thiệu khái niệm \"hygge\" của người Đan Mạch, một lối sống đề cao sự ấm cúng, giản dị và tận hưởng những khoảnh khắc nhỏ bé trong đời sống thường ngày. Tác giả trình bày các yếu tố tạo nên hygge như ánh nến, không gian sống ấm áp, ẩm thực và sự kết nối với gia đình, bạn bè. Cuốn sách được xem là một trong những lý do giúp lý giải vì sao Đan Mạch thường xuyên đứng đầu các bảng xếp hạng quốc gia hạnh phúc nhất thế giới."],
      ["Lagom - The Swedish Art Of Balanced Living", "Linnea Dunne", undefined, "Cuốn sách giới thiệu triết lý sống \"lagom\" của người Thụy Điển, có thể hiểu nôm na là \"vừa đủ\" - không quá nhiều cũng không quá ít. Tác giả Linnea Dunne trình bày cách áp dụng lagom vào nhiều khía cạnh đời sống như công việc, ẩm thực, không gian sống và các mối quan hệ để đạt được sự cân bằng. Cuốn sách khuyến khích độc giả tìm kiếm sự điều độ và hài lòng với những gì vừa phải thay vì chạy theo sự dư thừa."],
      ["Sisu - Vượt Qua Tất Cả", "Katja Pantzar", undefined, "Cuốn sách giới thiệu khái niệm \"sisu\" trong văn hóa Phần Lan, chỉ nghị lực và sự kiên cường giúp con người vượt qua nghịch cảnh và thử thách trong cuộc sống. Tác giả Katja Pantzar, một nhà báo gốc Canada sinh sống tại Phần Lan, kết hợp trải nghiệm cá nhân với các nghiên cứu khoa học để lý giải cách người Phần Lan rèn luyện sức bền bỉ về thể chất lẫn tinh thần. Cuốn sách đưa ra những gợi ý thực tế như tắm nước lạnh, vận động ngoài trời để nuôi dưỡng tinh thần sisu trong đời sống hiện đại."],
      ["Nghệ Thuật Tinh Tế Của Việc Đếch Quan Tâm", "Mark Manson", undefined, "Cuốn sách phản biện lại xu hướng tư duy tích cực thái quá phổ biến trong dòng sách self-help, cho rằng con người nên chọn lọc kỹ những điều thực sự đáng để quan tâm thay vì cố gắng làm hài lòng tất cả mọi thứ. Mark Manson lập luận rằng chấp nhận giới hạn, thất bại và những cảm xúc tiêu cực là một phần tất yếu của cuộc sống ý nghĩa. Thông qua giọng văn thẳng thắn, hài hước, tác giả khuyến khích độc giả xác định lại hệ giá trị của bản thân để sống chân thực và có trách nhiệm hơn."],
      ["Đi Tìm Lẽ Sống", "Viktor E. Frankl", undefined, "Cuốn sách kể lại trải nghiệm của tác giả, một bác sĩ tâm thần người Áo gốc Do Thái, trong các trại tập trung của Đức Quốc xã trong Thế chiến thứ hai. Từ những trải nghiệm khổ đau tột cùng đó, Viktor Frankl phát triển liệu pháp ý nghĩa (logotherapy), cho rằng con người có thể tìm thấy ý nghĩa sống ngay cả trong hoàn cảnh khắc nghiệt nhất. Cuốn sách khẳng định rằng chính việc tìm ra mục đích và ý nghĩa cá nhân là động lực cốt lõi giúp con người vượt qua nghịch cảnh."],
      ["Tuổi Trẻ Đáng Giá Bao Nhiêu", "Rosie Nguyễn", undefined, "Cuốn sách tập hợp những chia sẻ, trải nghiệm và suy ngẫm của tác giả Rosie Nguyễn về hành trình tuổi trẻ, việc học tập, đi du lịch bụi và khám phá bản thân. Tác giả khuyến khích người trẻ chủ động đọc sách, trải nghiệm thế giới và dấn thân thay vì sống an toàn, thụ động. Cuốn sách được xem là một trong những tác phẩm truyền cảm hứng phổ biến với độc giả trẻ Việt Nam về việc sống có mục tiêu và tận dụng thời gian tuổi trẻ."],
      ["Mong Mọi Sự Gặp Gỡ Đều Đúng Thời Điểm", "DTT"],
      ["Mơ Những Giấc Mơ Mới", "Jai Pausch", undefined, "Cuốn sách là hồi ký của Jai Pausch, vợ của giáo sư Randy Pausch - tác giả cuốn \"Bài Giảng Cuối Cùng\" nổi tiếng, kể về hành trình chăm sóc chồng khi ông mắc bệnh ung thư tụy giai đoạn cuối. Tác giả chia sẻ những khó khăn, mất mát và cách bà vượt qua nỗi đau để một mình nuôi dạy ba con nhỏ sau khi chồng qua đời. Cuốn sách là câu chuyện về nghị lực, tình yêu thương gia đình và cách xây dựng lại cuộc sống sau biến cố lớn."],
      ["Ngày Thứ Ba Với Morrie", "Mitch Albom", undefined, "Cuốn sách kể lại những buổi gặp gỡ hằng tuần vào thứ Ba giữa tác giả Mitch Albom và người thầy cũ của mình, giáo sư Morrie Schwartz, khi ông đang ở giai đoạn cuối của bệnh xơ cứng teo cơ (ALS). Qua các cuộc trò chuyện, Morrie chia sẻ những chiêm nghiệm sâu sắc về cuộc sống, cái chết, tình yêu, gia đình và cách sống có ý nghĩa. Cuốn sách trở thành một trong những tác phẩm hồi ký - triết lý sống được yêu thích rộng rãi trên thế giới."],
      ["Sức Mạnh Của Hiện Tại", "Eckhart Tolle", undefined, "Cuốn sách trình bày triết lý sống tập trung vào giây phút hiện tại, cho rằng phần lớn khổ đau của con người bắt nguồn từ việc tâm trí bị chi phối bởi những suy nghĩ về quá khứ và lo âu về tương lai. Eckhart Tolle giới thiệu khái niệm \"bản ngã\" (ego) như nguồn gốc của đau khổ và hướng dẫn độc giả cách quan sát, buông bỏ dòng suy nghĩ để đạt trạng thái tỉnh thức. Cuốn sách kết hợp các yếu tố từ Phật giáo, Thiền và các truyền thống tâm linh phương Đông để hướng đến sự bình an nội tâm."],
      ["Nghĩ Giàu Làm Giàu", "Napoleon Hill", undefined, "Cuốn sách được viết dựa trên quá trình tác giả Napoleon Hill nghiên cứu và phỏng vấn hàng trăm doanh nhân, triệu phú thành công tại Mỹ trong nhiều năm, trong đó có Andrew Carnegie. Tác phẩm đúc kết những nguyên tắc và tư duy chung dẫn đến thành công và sự giàu có, như khát vọng cháy bỏng, niềm tin, sự kiên trì và tư duy có tổ chức. Đây là một trong những cuốn sách kinh điển của thể loại phát triển bản thân và làm giàu, có ảnh hưởng lớn đến nhiều thế hệ độc giả."],
      ["999 Lá Thư Gửi Cho Chính Mình", "Miêu Công Tử"],
      ["1% Each Day", "Ngô Di Lân"],
    ],
  },
  {
    t: "VII. Việt Nam",
    n: 31,
    items: [
      ["Quảy Gánh Băng Đồng Ra Thế Giới", "Nguyễn Phi Vân", undefined, "Cuốn sách chia sẻ hành trình sự nghiệp quốc tế của tác giả Nguyễn Phi Vân, một chuyên gia trong lĩnh vực nhượng quyền và bán lẻ đã làm việc tại nhiều quốc gia trên thế giới. Qua những câu chuyện và trải nghiệm thực tế, tác giả đưa ra lời khuyên cho người trẻ Việt Nam về cách chuẩn bị hành trang, tư duy và kỹ năng để tự tin bước ra môi trường làm việc toàn cầu. Cuốn sách nhấn mạnh tinh thần chủ động học hỏi, thích nghi văn hóa và không ngừng phát triển bản thân trong bối cảnh hội nhập quốc tế."],
      ["Đừng Tháo Xuống Nụ Cười", "Khải Đơn"],
      ["Nỗi Buồn Chiến Tranh", "Bảo Ninh", undefined, "Tiểu thuyết kể về cuộc đời của Kiên, một người lính từng chiến đấu trong chiến tranh Việt Nam, qua dòng hồi tưởng đan xen giữa quá khứ chiến trường khốc liệt và hiện tại thời hậu chiến. Tác phẩm khắc họa những mất mát, ám ảnh tâm lý và bi kịch tình yêu mà chiến tranh để lại trong tâm hồn người lính, thay vì tập trung vào chiến thắng hay anh hùng ca. Đây là một trong những tiểu thuyết Việt Nam nổi tiếng nhất viết về chiến tranh, được dịch ra nhiều thứ tiếng và nhận nhiều giải thưởng quốc tế."],
      ["Tuổi Thơ Dữ Dội", "Phùng Quán", undefined, "Tiểu thuyết kể về những thiếu niên trinh sát nhỏ tuổi tham gia kháng chiến chống Pháp tại Huế, phải đối mặt với gian khổ, hiểm nguy và sự trưởng thành sớm giữa khói lửa chiến tranh. Tác phẩm khắc họa tình bạn, lòng dũng cảm và sự hy sinh của các em thiếu nhi trong hoàn cảnh chiến tranh khốc liệt. Đây là một trong những tác phẩm văn học kinh điển của Việt Nam viết về đề tài thiếu nhi trong kháng chiến, được nhiều thế hệ độc giả yêu thích."],
      ["Yêu Thương Là Tự Do", "Trần Lê Sơn Ý"],
      ["Quê Ngoại", "Hồ Dzếnh"],
      ["Trở Về Nơi Hoang Dã", "Trang Nguyễn", undefined, "Cuốn sách kể về hành trình của Trang Nguyễn, nhà bảo tồn động vật hoang dã người Việt Nam, từ niềm đam mê thiên nhiên thời thơ ấu đến việc theo đuổi sự nghiệp bảo vệ các loài động vật quý hiếm trên thế giới. Tác giả chia sẻ những trải nghiệm thực tế khi làm việc tại các khu bảo tồn ở châu Phi và châu Á, đối mặt với nạn săn bắt trái phép và buôn bán động vật hoang dã. Cuốn sách truyền tải thông điệp về tình yêu thiên nhiên và trách nhiệm bảo vệ môi trường sống của các loài động vật."],
      ["Một Mình Ở Châu Âu", "Phan Việt", undefined, "Cuốn sách là tập hồi ký, phần đầu trong bộ ba tác phẩm của Phan Việt, ghi lại chuyến đi một mình của tác giả qua nhiều thành phố ở châu Âu trong giai đoạn khủng hoảng cá nhân. Qua hành trình di chuyển và những cuộc gặp gỡ, tác giả chiêm nghiệm về đời sống hôn nhân, mất mát và quá trình tìm lại chính mình. Cuốn sách kết hợp giữa du ký và tự sự nội tâm, phản ánh những suy tư sâu sắc về hạnh phúc và ý nghĩa cuộc sống."],
      ["Một Nghệ Thuật Sống", "Nguyễn Duy Cần", undefined, "Cuốn sách của học giả Nguyễn Duy Cần (bút hiệu Thu Giang) bàn về nghệ thuật sống dựa trên nền tảng triết học phương Đông, đặc biệt là tư tưởng Lão Trang. Tác giả trình bày quan niệm về sự ung dung, tự tại, biết đủ và hòa hợp với tự nhiên như những nguyên tắc cốt lõi để có một cuộc sống an nhiên. Cuốn sách là một trong nhiều tác phẩm của Nguyễn Duy Cần nhằm giới thiệu minh triết phương Đông đến độc giả Việt Nam."],
      ["Có Một Phố Vừa Đi Qua Phố", "Đinh Vũ Hoàng Nguyên", undefined, "Cuốn sách là tuyển tập tản văn, thơ và tranh minh họa của Đinh Vũ Hoàng Nguyên, một họa sĩ biếm họa kiêm nhà văn qua đời vì bệnh ung thư gan ở tuổi ngoài ba mươi. Tác phẩm ghi lại những quan sát tinh tế, hài hước và giàu cảm xúc về đời sống thường nhật của Hà Nội, con người và những góc phố quen thuộc. Cuốn sách được xuất bản sau khi tác giả qua đời và được nhiều độc giả yêu mến bởi giọng văn chân thực, gần gũi."],
      ["Dăm Ba Cái Tuổi Trẻ", "Spiderum"],
      ["Hồn Bướm Mơ Tiên", "Khái Hưng", undefined, "Tiểu thuyết kể về câu chuyện tình cảm trong sáng, đầy giằng xé giữa Ngọc, một chàng sinh viên, và Lan, một ni cô tu tại chùa Long Giáng. Tác phẩm thể hiện xung đột giữa tình yêu đôi lứa và giới luật tu hành, giữa khát vọng cá nhân và lễ giáo phong kiến đương thời. Đây được xem là tiểu thuyết mở đầu cho trào lưu văn học lãng mạn của nhóm Tự Lực Văn Đoàn tại Việt Nam."],
      ["Số Đỏ", "Vũ Trọng Phụng", undefined, "Tiểu thuyết trào phúng kể về Xuân Tóc Đỏ, một kẻ vô học, lưu manh vặt bất ngờ nhờ may mắn và mánh khóe mà leo lên địa vị cao trong xã hội thượng lưu thành thị thời Pháp thuộc. Qua nhân vật này, tác giả Vũ Trọng Phụng châm biếm sâu cay thói giả dối, lố lăng và sự tha hóa đạo đức của xã hội Việt Nam đương thời trong quá trình Âu hóa nửa vời. Tác phẩm được xem là một trong những kiệt tác trào phúng xuất sắc nhất của văn học Việt Nam hiện đại."],
      ["Vang Bóng Một Thời", "Nguyễn Tuân", undefined, "Tập truyện ngắn khắc họa lại những thú chơi tao nhã và nếp sống tài hoa của tầng lớp nho sĩ, trí thức phong kiến Việt Nam trong buổi giao thời, như thưởng trà, chơi chữ, thả thơ. Tác giả Nguyễn Tuân dùng ngòi bút tài hoa, giàu chất thẩm mỹ để tái hiện một thời đại đã lùi vào dĩ vãng cùng những giá trị văn hóa truyền thống đang dần mai một. Tác phẩm được đánh giá là một trong những đỉnh cao của thể loại truyện ngắn trong văn học Việt Nam hiện đại."],
      ["Một Cơn Gió Bụi", "Trần Trọng Kim", undefined, "Cuốn hồi ký của học giả Trần Trọng Kim ghi lại giai đoạn ông tham gia chính trường với vai trò Thủ tướng của Đế quốc Việt Nam năm 1945, dưới sự bảo trợ của Nhật Bản trong bối cảnh lịch sử đầy biến động. Tác giả thuật lại những sự kiện chính trị, xã hội quan trọng mà ông trực tiếp chứng kiến và tham gia trong giai đoạn chuyển giao quyền lực tại Việt Nam. Cuốn sách được xem là một tư liệu lịch sử quý giá phản ánh góc nhìn của người trong cuộc về một giai đoạn lịch sử phức tạp."],
      ["Chuyến Tàu Một Chiều Không Trở Lại", "Kiên Trần"],
      ["Lập Trình Quỹ Đạo Cuộc Đời", "Kiên Trần"],
      ["Đừng Chạy Theo Đám Đông", "Kiên Trần"],
      ["Giang Hồ Chỉ Vừa Đủ Xài", "Trang Hạ"],
      ["Hai Mươi Bảy", "Đặng Huỳnh Mai Anh"],
      ["Người Tị Nạn", "Viet Thanh Nguyen", undefined, "Tập truyện ngắn khắc họa cuộc sống của những người Việt tị nạn và con cái họ tại Mỹ sau chiến tranh Việt Nam, với những giằng xé giữa quá khứ và hiện tại, giữa hai nền văn hóa. Tác giả Viet Thanh Nguyen, người từng đoạt giải Pulitzer với tiểu thuyết \"Cảm Tình Viên\", khắc họa sâu sắc bản sắc, ký ức và sự mất mát của cộng đồng người tị nạn. Các câu chuyện trong tập truyện phản ánh những trải nghiệm đa dạng về hòa nhập, cô đơn và tìm kiếm căn tính giữa hai thế giới."],
      ["Rèn Nghị Lực Để Lập Thân", "Nguyễn Hiến Lê", undefined, "Cuốn sách của học giả Nguyễn Hiến Lê bàn về vai trò của nghị lực trong việc xây dựng sự nghiệp và nhân cách con người. Tác giả phân tích những phẩm chất cần thiết để rèn luyện ý chí như kiên trì, tự chủ và khả năng vượt qua khó khăn, kết hợp với các dẫn chứng từ danh nhân trong lịch sử. Đây là một trong nhiều tác phẩm thuộc dòng sách \"học làm người\" mà Nguyễn Hiến Lê biên soạn nhằm hướng dẫn thanh niên Việt Nam tu dưỡng bản thân."],
      ["Đàn Bà Ba Mươi", "Trang Hạ"],
      ["Chênh Vênh Hai Lăm", "Nguyễn Ngọc Thạch"],
      ["Tôi 20++", "Nick D."],
      ["Khóc Giữa Sài Gòn", "Nguyễn Ngọc Thạch", undefined, "Tiểu thuyết của nhà văn Nguyễn Ngọc Thạch xoay quanh câu chuyện tình cảm và những khó khăn, định kiến mà các nhân vật đồng tính phải đối mặt trong bối cảnh xã hội Sài Gòn hiện đại. Tác phẩm khai thác đề tài giới tính và tình yêu đồng giới, một chủ đề còn khá mới mẻ trong văn học đại chúng Việt Nam vào thời điểm xuất bản. Cuốn sách góp phần đưa những câu chuyện về cộng đồng LGBT đến gần hơn với độc giả phổ thông trong nước."],
      ["Tớ Là Dâu", "Joe Ruelle", undefined, "Cuốn sách của Joe Ruelle (biệt danh Dâu Tây), một người Canada sinh sống lâu năm tại Việt Nam, viết bằng tiếng Việt kể về những trải nghiệm và góc nhìn của một người nước ngoài khi hòa nhập vào văn hóa, phong tục và đời sống thường ngày của người Việt. Tác giả sử dụng giọng văn hài hước, dí dỏm để kể lại những tình huống dở khóc dở cười trong quá trình học tiếng Việt và làm quen với lối sống bản địa. Cuốn sách mang đến góc nhìn thú vị, mới mẻ về văn hóa Việt Nam qua con mắt của một người ngoại quốc."],
      ["Lỏng Và Tuột", "Trần Đức Tiến"],
      ["Bức Xúc Không Làm Ta Vô Can", "Đặng Hoàng Giang", undefined, "Cuốn sách tập hợp các bài viết của tiến sĩ Đặng Hoàng Giang phân tích những hiện tượng xã hội đáng chú ý tại Việt Nam, như bạo lực mạng, sự vô cảm, đám đông và tâm lý đổ lỗi. Tác giả chỉ ra rằng sự bức xúc, phẫn nộ nhất thời trên mạng xã hội không đồng nghĩa với hành động có trách nhiệm, mà đôi khi còn là một hình thức trốn tránh trách nhiệm cá nhân. Cuốn sách khuyến khích độc giả nhìn nhận các vấn đề xã hội một cách thấu đáo, tỉnh táo hơn thay vì chạy theo cảm xúc đám đông."],
      ["Một Đời Như Kẻ Tìm Đường", "Phan Văn Trường", "Đang đọc (30%)", "Cuốn sách là những chia sẻ, chiêm nghiệm của giáo sư Phan Văn Trường, một người Việt có sự nghiệp quốc tế thành công trong lĩnh vực đàm phán thương mại tại Pháp, về hành trình cuộc đời và những bài học rút ra qua từng giai đoạn. Tác giả kể lại các quyết định quan trọng, thử thách và cơ duyên đã định hình sự nghiệp của mình, đồng thời gửi gắm những lời khuyên cho thế hệ trẻ về cách chọn con đường đi cho riêng mình. Cuốn sách nhấn mạnh tinh thần không ngừng học hỏi, thích nghi và giữ vững giá trị đạo đức trong suốt hành trình sự nghiệp."],
      ["Hành Tinh Của Một Kẻ Nghĩ Nhiều", "Nguyễn Đoàn Minh Thư"],
    ],
  },
{
    t: "VIII. Tiểu thuyết nước ngoài",
    n: 62,
    items: [
      ["Những Con Chim Ẩn Mình Chờ Chết", "Colleen McCullough", undefined, "Tiểu thuyết kể về ba thế hệ của gia đình Cleary sinh sống trên vùng đất Drogheda hoang sơ ở Úc trong nửa đầu thế kỷ 20. Trọng tâm câu chuyện là mối tình cấm đoán và đầy giằng xé giữa Meggie Cleary và vị linh mục Ralph de Bricassart, người phải lựa chọn giữa tình yêu trần thế và con đường sự nghiệp trong Giáo hội. Xuyên suốt tác phẩm là hình ảnh loài chim huyền thoại chỉ cất tiếng hót hay nhất một lần trong đời, ngay trước khi tự đâm mình vào gai nhọn mà chết, ẩn dụ cho những hy sinh và đau khổ vì tình yêu của các nhân vật."],
      ["Phía Nam Biên Giới, Phía Tây Mặt Trời", "Haruki Murakami", undefined, "Tiểu thuyết xoay quanh Hajime, một người đàn ông trung niên sống cuộc đời tưởng như viên mãn với vợ con và quán bar jazz riêng ở Tokyo. Cuộc sống của anh xáo trộn khi Shimamoto, mối tình đầu thời thơ ấu đã biến mất bí ẩn nhiều năm trước, bất ngờ xuất hiện trở lại. Sự trở lại của Shimamoto khơi dậy trong Hajime những khát khao và ám ảnh cũ, đẩy anh vào cuộc đấu tranh nội tâm giữa trách nhiệm gia đình và tiếng gọi của quá khứ."],
      ["Sự Im Lặng Của Bầy Cừu", "Thomas Harris", undefined, "Tiểu thuyết kể về Clarice Starling, một học viên FBI được giao nhiệm vụ thẩm vấn Hannibal Lecter, bác sĩ tâm thần kiêm kẻ giết người hàng loạt đang bị giam giữ, để tìm manh mối về một tên sát nhân khác có biệt danh Buffalo Bill. Buffalo Bill chuyên bắt cóc và lột da các nạn nhân nữ, khiến FBI phải chạy đua với thời gian để cứu con tin mới nhất. Qua những cuộc đối thoại đầy trí tuệ và nguy hiểm với Lecter, Clarice dần khám phá ra manh mối giúp phá án, đồng thời đối mặt với những góc khuất tâm lý của chính mình."],
      ["Bức Tranh Dorian Gray", "Oscar Wilde", undefined, "Chàng trai trẻ đẹp Dorian Gray ước rằng bức chân dung của mình sẽ già đi thay cho anh, để bản thân mãi mãi giữ được vẻ đẹp và tuổi trẻ. Điều ước kỳ lạ ấy trở thành sự thật: trong khi Dorian sống buông thả, sa đọa và phạm nhiều tội ác, bức tranh của anh dần biến dạng, ghi lại mọi dấu vết tội lỗi và thời gian. Cuối cùng, gánh nặng tội lỗi và nỗi ám ảnh về bức tranh đẩy Dorian đến một kết cục bi thảm."],
      ["The Perks Of Being A Wallflower", "Stephen Chbosky", undefined, "Tiểu thuyết được viết dưới dạng những lá thư của Charlie, một cậu học sinh năm nhất trung học nhút nhát, gửi cho một người bạn ẩn danh không rõ danh tính. Qua những lá thư, Charlie kể về quá trình hòa nhập với nhóm bạn mới gồm Sam và Patrick, cùng những trải nghiệm đầu đời về tình bạn, tình yêu, ma túy và mất mát. Song song đó, cậu dần đối diện với những sang chấn tâm lý từ quá khứ, đặc biệt là ký ức về người dì đã mất."],
      ["Sông Đông Êm Đềm", "Mikhail Sholokhov", undefined, "Bộ tiểu thuyết sử thi tái hiện cuộc sống của cộng đồng người Cossack bên dòng sông Đông trong giai đoạn biến động của nước Nga đầu thế kỷ 20, từ trước Thế chiến thứ nhất đến nội chiến Nga. Nhân vật chính Grigori Melekhov giằng xé giữa tình yêu với hai người phụ nữ, Natalia và Aksinia, đồng thời chao đảo giữa các phe phái chính trị đối lập trong cuộc nội chiến. Tác phẩm khắc họa số phận bi kịch của con người bị cuốn vào vòng xoáy chiến tranh và những đổi thay dữ dội của lịch sử."],
      ["Ba Ơi, Mình Đi Đâu?", "Jean-Louis Fournier", undefined, "Đây là cuốn hồi ký của nhà văn Jean-Louis Fournier viết cho hai người con trai của ông, cả hai đều mắc chứng thiểu năng trí tuệ bẩm sinh. Bằng giọng văn hài hước pha lẫn chua xót, tác giả kể lại những khó khăn, nỗi đau và cả những khoảnh khắc ấm áp trong hành trình làm cha của những đứa trẻ khuyết tật. Cuốn sách đặt ra câu hỏi về ý nghĩa của tình phụ tử và cách con người đối diện với những điều không may mắn trong cuộc sống."],
      ["Cha Và Con", "Cormac McCarthy", undefined, "Tiểu thuyết kể về hành trình của một người cha và cậu con trai nhỏ băng qua vùng đất Bắc Mỹ hoang tàn sau một thảm họa không được nêu rõ nguyên nhân. Trên đường đi về phía bờ biển phía nam để tìm kiếm sự sống sót, hai cha con phải đối mặt với đói khát, cái lạnh và mối đe dọa từ những nhóm người man rợ còn sót lại. Xuyên suốt hành trình, người cha luôn cố gắng bảo vệ và truyền lại cho con niềm tin vào lòng tốt giữa một thế giới đã mất hết đạo đức."],
      ["Con Đường Da Cam", "David Zierler", undefined, "Cuốn sách nghiên cứu lịch sử kể về cuộc chiến tranh hóa học của Mỹ tại Việt Nam thông qua việc sử dụng thuốc diệt cỏ, sau này được gọi là chất da cam, nhằm phá hủy rừng và triệt phá lương thực của lực lượng du kích. Tác giả David Zierler tiếp cận vấn đề từ cả góc độ khoa học lẫn chính trị, lý giải nguồn gốc, cơ chế hủy diệt cây cối của loại hóa chất này cũng như quá trình sản xuất và triển khai nó trong chiến tranh. Cuốn sách còn khắc họa phong trào phản đối của giới khoa học Mỹ trước việc sử dụng chất da cam, đặt vấn đề này trong bối cảnh Chiến tranh Lạnh và sự trỗi dậy của phong trào bảo vệ môi trường."],
      ["Nỗi Cô Đơn Của Các Số Nguyên Tố", "Paolo Giordano", undefined, "Tiểu thuyết kể về Mattia và Alice, hai đứa trẻ mang trong mình những tổn thương tâm lý sâu sắc từ thời thơ ấu: Mattia day dứt vì đã bỏ rơi người em gái sinh đôi thiểu năng trí tuệ dẫn đến cái chết của em, còn Alice mang di chứng thể chất và tâm lý sau một tai nạn trượt tuyết. Hai người gặp nhau ở trường trung học và hình thành một mối liên kết đặc biệt, giống như những số nguyên tố sinh đôi - luôn ở gần nhau nhưng không bao giờ thực sự chạm được vào nhau. Tác phẩm theo chân họ qua nhiều năm trưởng thành, khắc họa sự cô đơn dai dẳng của những con người không thể hòa nhập trọn vẹn với thế giới xung quanh."],
      ["Giáo Sư Và Công Thức Toán", "Yōko Ogawa", undefined, "Tiểu thuyết kể về một giáo sư toán học thiên tài nhưng do di chứng tai nạn chỉ còn trí nhớ ngắn hạn kéo dài đúng 80 phút. Một người giúp việc trẻ cùng cậu con trai nhỏ của cô, được giáo sư đặt biệt danh là Căn Bậc Hai, dần xây dựng mối quan hệ gắn bó với ông mỗi ngày như thể lần đầu gặp gỡ. Qua những con số, công thức toán học và niềm đam mê bóng chày, câu chuyện khắc họa vẻ đẹp giản dị của tình người vượt lên trên giới hạn của trí nhớ và thời gian."],
      ["Ngàn Mặt Trời Rực Rỡ", "Khaled Hosseini", undefined, "Tiểu thuyết kể về cuộc đời của hai người phụ nữ Afghanistan, Mariam và Laila, thuộc hai thế hệ khác nhau nhưng cùng bị ép gả cho một người đàn ông vũ phu tên Rasheed. Trải qua chiến tranh, áp bức và bất công dưới các chế độ cai trị khác nhau ở Afghanistan, hai người phụ nữ ban đầu thù ghét nhau dần trở thành chỗ dựa tinh thần cho nhau. Câu chuyện khắc họa sức mạnh của tình bạn và đức hy sinh của người phụ nữ giữa hoàn cảnh chiến tranh và bất bình đẳng giới khắc nghiệt."],
      ["Cánh Cửa", "Magda Szabó", undefined, "Tiểu thuyết kể về mối quan hệ phức tạp giữa một nữ nhà văn và Emerence, người giúp việc lớn tuổi bí ẩn và ương ngạnh của bà. Emerence không bao giờ cho ai bước vào nhà mình, che giấu một quá khứ đau thương mà chỉ dần hé lộ qua thời gian gắn bó giữa hai người phụ nữ. Câu chuyện khám phá ranh giới giữa tình yêu thương, sự kiểm soát và những bí mật có thể hủy hoại một mối quan hệ."],
      ["Âm Thanh Và Cuồng Nộ", "William Faulkner", undefined, "Tiểu thuyết kể về sự suy tàn của gia đình Compson, một dòng họ quý tộc miền Nam nước Mỹ, qua bốn phần được kể từ góc nhìn của ba anh em trai và một người kể chuyện toàn tri. Trọng tâm câu chuyện xoay quanh Caddy Compson, người em gái mà cả ba anh trai đều gắn bó sâu sắc, và sự sa sút của gia đình sau khi cô rời bỏ nhà. Tác phẩm nổi tiếng với kỹ thuật dòng ý thức phức tạp, đặc biệt qua góc nhìn của Benjy, người em trai thiểu năng trí tuệ."],
      ["Thiếu Nữ Đánh Cờ Vây", "Shan Sa", undefined, "Tiểu thuyết lấy bối cảnh Mãn Châu những năm 1930, khi Nhật Bản chiếm đóng Trung Quốc, kể về mối tình bí mật nảy sinh giữa một thiếu nữ Trung Quốc và một sĩ quan Nhật Bản cải trang. Hai người gặp nhau và dần yêu nhau qua những ván cờ vây tại một quảng trường công cộng, mà không hề biết đối phương thuộc phe địch của mình. Câu chuyện được kể luân phiên qua góc nhìn của hai nhân vật, dẫn đến một kết cục bi kịch khi chiến tranh buộc họ phải đối mặt với sự thật."],
      ["Triệu Phú Khu Ổ Chuột", "Vikas Swarup", undefined, "Tiểu thuyết kể về Ram Mohammad Thomas, một chàng trai mồ côi lớn lên trong khu ổ chuột ở Ấn Độ, bị bắt giữ vì bị nghi gian lận sau khi trả lời đúng toàn bộ câu hỏi trong một chương trình truyền hình đố vui triệu phú. Trong lúc bị thẩm vấn, anh lần lượt kể lại những biến cố trong cuộc đời mình, mỗi câu chuyện lại vô tình giải thích vì sao anh biết đáp án cho từng câu hỏi trong chương trình. Tác phẩm là nguồn cảm hứng cho bộ phim nổi tiếng Slumdog Millionaire."],
      ["Where Rainbows End", "Cecelia Ahern", undefined, "Tiểu thuyết kể về Rosie và Alex, đôi bạn thân từ thuở nhỏ tại Dublin, qua hình thức những lá thư, email và tin nhắn trao đổi suốt nhiều thập kỷ. Dù luôn dành tình cảm đặc biệt cho nhau, hai người liên tục lỡ hẹn vì hoàn cảnh, khoảng cách địa lý và những mối quan hệ khác trong cuộc sống. Câu chuyện theo chân họ từ tuổi thiếu niên đến khi trưởng thành, khắc họa hành trình dài để cuối cùng tìm được nhau."],
      ["Nỗi Đau Của Chàng Werther", "Johann Wolfgang von Goethe", undefined, "Tiểu thuyết dưới hình thức thư từ kể về Werther, một chàng trai trẻ nhạy cảm và giàu cảm xúc, người đem lòng yêu say đắm Lotte dù nàng đã đính hôn với người khác. Không thể từ bỏ tình cảm của mình nhưng cũng không thể chiếm được trái tim Lotte, Werther rơi vào tuyệt vọng và giằng xé nội tâm ngày càng sâu sắc. Cuối cùng, không tìm được lối thoát cho nỗi đau tình yêu, Werther chọn cách tự kết liễu đời mình."],
      ["Đo Thế Giới", "Daniel Kehlmann", undefined, "Tiểu thuyết kể song song cuộc đời của hai nhà khoa học Đức đầu thế kỷ 19: nhà toán học Carl Friedrich Gauss, người đo đạc thế giới bằng trí tuệ và các phép tính trong phòng làm việc, và nhà tự nhiên học Alexander von Humboldt, người đo đạc thế giới bằng những chuyến thám hiểm gian khổ khắp châu Mỹ. Dù có phương pháp và tính cách trái ngược nhau, cả hai đều theo đuổi khát vọng thấu hiểu và đo lường vũ trụ bằng khoa học. Cuốn tiểu thuyết pha trộn yếu tố lịch sử có thật với hư cấu hài hước, khắc họa tinh thần Khai sáng châu Âu."],
      ["Hyperbole And A Half", "Allie Brosh", undefined, "Đây là tuyển tập các bài viết và tranh vẽ minh họa hài hước của tác giả kiêm họa sĩ Allie Brosh, chuyển thể từ blog cùng tên của cô. Cuốn sách kể lại những câu chuyện đời thường như kỷ niệm thơ ấu, hai chú chó tính cách kỳ quặc của tác giả, đan xen với những trải nghiệm chân thực và đau đớn về chứng trầm cảm mà cô từng trải qua. Bằng phong cách vẽ đơn giản kết hợp lối kể chuyện tự trào, tác phẩm mang đến cái nhìn vừa hài hước vừa sâu sắc về sức khỏe tâm thần."],
      ["Bí Kíp Quá Giang Vào Ngân Hà", "Douglas Adams", undefined, "Tiểu thuyết khoa học viễn tưởng hài hước kể về Arthur Dent, người Trái Đất duy nhất sống sót sau khi hành tinh của anh bị phá hủy để nhường chỗ cho một xa lộ không gian. Được người bạn ngoài hành tinh Ford Prefect - một cộng tác viên của cuốn cẩm nang du hành Hitchhiker's Guide to the Galaxy - cứu thoát, Arthur bắt đầu chuyến phiêu lưu kỳ quặc khắp vũ trụ. Trên hành trình, họ gặp gỡ nhiều nhân vật kỳ lạ như Zaphod Beeblebrox, Trillian và robot Marvin, khám phá những bí ẩn hài hước về ý nghĩa cuộc sống, vũ trụ và vạn vật."],
      ["Biên Niên Ký Chim Vặn Dây Cót", "Haruki Murakami", undefined, "Tiểu thuyết kể về Toru Okada, một người đàn ông thất nghiệp ở Tokyo, khởi đầu hành trình kỳ lạ khi đi tìm con mèo thất lạc của gia đình rồi sau đó là người vợ Kumiko biến mất bí ẩn. Trong quá trình tìm kiếm, anh gặp gỡ nhiều nhân vật kỳ dị và dần bị cuốn vào một thế giới pha trộn giữa thực tại và siêu thực, gắn với những bí mật từ quá khứ chiến tranh của Nhật Bản. Câu chuyện đan xen nhiều tầng lớp thời gian và không gian, khắc họa hành trình tìm lại bản thân và những mối liên hệ vô hình giữa con người."],
      ["Kafka Bên Bờ Biển", "Haruki Murakami", undefined, "Tiểu thuyết kể song song hai câu chuyện: Kafka Tamura, cậu bé mười lăm tuổi bỏ nhà ra đi để trốn tránh lời nguyền của cha và tìm kiếm mẹ cùng chị gái đã thất lạc, và Nakata, một ông già kỳ lạ mất khả năng đọc chữ sau một sự cố thời thơ ấu nhưng có thể trò chuyện với loài mèo. Hai hành trình tưởng chừng tách biệt dần giao thoa với nhau qua những sự kiện siêu thực đầy ẩn dụ. Tác phẩm pha trộn hiện thực và huyền ảo, khám phá các chủ đề về định mệnh, ký ức và sự trưởng thành."],
      ["Đồi Gió Hú", "Emily Brontë", undefined, "Tiểu thuyết kể về mối tình đầy ám ảnh và thù hận giữa Heathcliff, một đứa trẻ vô thừa nhận được gia đình Earnshaw nhận nuôi, và Catherine Earnshaw, cô con gái của gia đình. Khi Catherine chọn kết hôn với người khác vì địa vị xã hội, Heathcliff rời đi rồi trở về giàu có để trả thù những người đã làm anh tổn thương, gieo rắc đau khổ cho cả hai thế hệ trong hai gia đình Earnshaw và Linton. Câu chuyện được kể lại qua lời của người quản gia Nelly Dean, khắc họa vòng xoáy của tình yêu, thù hận và sự trả thù trên vùng đồng hoang nước Anh."],
      ["Sống Như Người Paris", "Anne Berest", undefined, "Đây là cuốn cẩm nang phi hư cấu do bốn tác giả nữ người Pháp - Anne Berest, Caroline de Maigret, Audrey Diwan và Sophie Mas - cùng chấp bút, chia sẻ bí quyết về phong cách sống, thời trang, tình yêu và sự quyến rũ của phụ nữ Paris. Cuốn sách đưa ra những lời khuyên thực tế về cách giữ gìn tình yêu, ứng xử trong hôn nhân, làm đẹp, nấu ăn và chăm sóc nhà cửa, kèm theo những địa chỉ yêu thích của các tác giả tại Paris. Với giọng văn hài hước pha lẫn những minh họa thời trang tinh tế, tác phẩm khắc họa chân dung người phụ nữ Paris cùng bầu không khí xã hội, văn hóa đã hình thành nên họ."],
      ["Trong Gia Đình", "Hector Malot", undefined, "Tiểu thuyết kể về Perrine, một cô bé mồ côi cha mẹ, phải một mình vượt qua chặng đường dài từ nước ngoài trở về Pháp để tìm người ông nội giàu có nhưng chưa từng gặp mặt. Vì ông nội có định kiến với cha của Perrine, người đã cưới một phụ nữ ngoại quốc, cô bé phải giấu thân phận thật và làm công nhân trong nhà máy của ông để dần lấy được lòng tin của ông. Cuối cùng, bằng sự thông minh, chăm chỉ và lòng nhân hậu, Perrine chứng minh được giá trị bản thân và được ông nội nhận làm cháu."],
      ["Trại Trẻ Đặc Biệt Của Cô Peregrine", "Ransom Riggs", undefined, "Tiểu thuyết kể về Jacob, một cậu thiếu niên sau cái chết bí ẩn của ông nội đã tìm đến một hòn đảo ở xứ Wales để khám phá sự thật về những câu chuyện ông từng kể. Tại đây, cậu phát hiện ra trại trẻ mồ côi bí ẩn do cô Peregrine điều hành, nơi những đứa trẻ sở hữu năng lực đặc biệt được bảo vệ khỏi những sinh vật nguy hiểm bằng một vòng lặp thời gian. Jacob dần khám phá ra mối liên hệ giữa bản thân mình với thế giới kỳ lạ này và vai trò mà cậu phải đảm nhận để bảo vệ những đứa trẻ đặc biệt đó."],
      ["Tình Yêu Thời Thổ Tả", "Gabriel García Márquez", undefined, "Tiểu thuyết kể về mối tình kéo dài hơn nửa thế kỷ của Florentino Ariza dành cho Fermina Daza, người phụ nữ mà anh yêu từ thời trẻ nhưng không thể kết hôn vì bị gia đình nàng ngăn cản. Fermina sau đó kết hôn với bác sĩ Juvenal Urbino, còn Florentino âm thầm chờ đợi và trải qua vô số mối quan hệ khác trong suốt cuộc đời, vẫn giữ nguyên tình yêu dành cho Fermina. Khi Urbino qua đời, Florentino cuối cùng có cơ hội bày tỏ lại tình cảm với Fermina lúc cả hai đã ở tuổi xế chiều."],
      ["Túp Lều Bác Tom", "Harriet Beecher Stowe", undefined, "Tiểu thuyết kể về cuộc đời của Tom, một người nô lệ da đen tốt bụng và mộ đạo, bị bán qua tay nhiều chủ nô khác nhau ở miền Nam nước Mỹ trước Nội chiến. Qua hành trình của Tom cùng nhiều nhân vật nô lệ khác như Eliza và con trai, tác phẩm phơi bày sự tàn bạo và phi nhân tính của chế độ nô lệ. Cuốn sách có ảnh hưởng lớn đến phong trào bãi nô ở Mỹ thế kỷ 19, đặc biệt trong giai đoạn dẫn đến Nội chiến."],
      ["Utopia", "Thomas More", undefined, "Tác phẩm mô tả một hòn đảo hư cấu tên Utopia, nơi có một xã hội lý tưởng được tổ chức theo nguyên tắc công hữu tài sản, không có tư hữu, giai cấp hay tiền bạc chi phối đời sống con người. Câu chuyện được kể qua lời nhân vật Raphael Hythloday, người từng đến thăm hòn đảo và mô tả lại các thể chế chính trị, xã hội, tôn giáo và phong tục kỳ lạ nhưng hài hòa của nơi đây. Qua đó, tác giả Thomas More phê phán những bất công trong xã hội châu Âu đương thời và đặt ra những vấn đề triết học về một xã hội công bằng lý tưởng."],
      ["Quần Đảo Ngục Tù", "Aleksandr Solzhenitsyn", undefined, "Tác phẩm ghi chép và phân tích hệ thống trại lao động cưỡng bức Gulag của Liên Xô, dựa trên trải nghiệm cá nhân của tác giả cũng như lời kể của hàng trăm cựu tù nhân khác. Cuốn sách mô tả chi tiết quá trình bắt giữ, thẩm vấn, xét xử và đày ải hàng triệu người bị coi là kẻ thù chính trị của nhà nước Xô Viết từ thời Lenin đến Stalin. Tác phẩm được coi là bằng chứng lịch sử quan trọng phơi bày bản chất đàn áp của chế độ toàn trị Xô Viết, gây chấn động dư luận quốc tế khi được xuất bản."],
      ["Ở Quán Cà Phê Của Tuổi Trẻ Lạc Lối", "Patrick Modiano", undefined, "Tiểu thuyết xoay quanh Louki, một cô gái bí ẩn thường xuất hiện tại quán cà phê Condé, nơi tụ tập của những thanh niên phóng khoáng và lạc lối ở khu Paris những năm 1950-1960. Câu chuyện về Louki được kể lại qua góc nhìn của nhiều nhân vật khác nhau từng quen biết cô, mỗi người nắm giữ một mảnh ghép khác nhau về con người và quá khứ bí ẩn của cô. Qua đó, tác phẩm khắc họa bầu không khí hoài niệm về Paris xưa cũ cùng cảm giác chông chênh, lạc lối của tuổi trẻ đi tìm bản ngã."],
      ["Khi Lỗi Thuộc Về Những Vì Sao", "John Green", undefined, "Tiểu thuyết kể về Hazel Grace Lancaster, một cô gái mắc bệnh ung thư tuyến giáp di căn phổi, gặp gỡ Augustus Waters tại một nhóm hỗ trợ dành cho bệnh nhân ung thư trẻ tuổi. Hai người nhanh chóng nảy sinh tình cảm và cùng nhau thực hiện chuyến đi đến Amsterdam để gặp tác giả cuốn sách yêu thích của Hazel. Tình yêu của họ tiếp tục phát triển ngay cả khi bệnh tình của Augustus trở nặng, đặt ra những suy ngẫm về ý nghĩa cuộc sống, tình yêu và cái chết ở tuổi trẻ."],
      ["Không Gia Đình", "Hector Malot", undefined, "Tiểu thuyết kể về Rémi, một cậu bé bị bỏ rơi từ nhỏ, lớn lên trong một gia đình nông dân nghèo trước khi bị bán cho cụ Vitalis, một nghệ sĩ lưu diễn già cùng đoàn xiếc thú nhỏ của ông. Rémi cùng cụ Vitalis rong ruổi khắp nước Pháp biểu diễn kiếm sống, trải qua nhiều gian truân, mất mát và tình bạn trên đường đi. Cuối cùng, qua nhiều biến cố, Rémi tìm lại được nguồn gốc thật sự và gia đình ruột thịt của mình."],
      ["Chai Thời Gian", "Prabhassorn Sevikul", undefined, "Tiểu thuyết kể về hành trình trưởng thành của năm nhân vật Nat, Porm, Chai, Eik và Jom, từ thuở nhỏ cho đến khi bước vào tuổi thanh niên tại Thái Lan. Câu chuyện khắc họa thế hệ học sinh, sinh viên Thái Lan thập niên 1970, với những rung động đầu đời, tình bạn, tình yêu cùng khoảng cách thế hệ giữa họ và cha mẹ. Tác phẩm phản ánh những trăn trở, mất mát và bài học trưởng thành của tuổi trẻ giữa bối cảnh xã hội Thái Lan nhiều biến động thời kỳ đó."],
      ["Ăn, Cầu Nguyện, Yêu", "Elizabeth Gilbert", undefined, "Đây là cuốn hồi ký kể về hành trình một năm của chính tác giả Elizabeth Gilbert sau khi ly hôn và trải qua khủng hoảng tinh thần, đi qua ba quốc gia Ý, Ấn Độ và Indonesia. Tại Ý, cô tận hưởng ẩm thực và niềm vui sống; tại Ấn Độ, cô tìm kiếm sự tĩnh tâm qua thiền định trong một tu viện; và tại Indonesia, cô tìm lại sự cân bằng giữa tinh thần và thể xác cùng một tình yêu mới. Cuốn sách kể lại hành trình tác giả tự chữa lành và tìm lại chính mình sau đổ vỡ."],
      ["Tôi Nói Gì Khi Nói Về Chạy Bộ", "Haruki Murakami", undefined, "Đây là tập hồi ký của Haruki Murakami, trong đó ông chia sẻ về thói quen chạy bộ đường dài đã gắn bó với ông từ khi bắt đầu sự nghiệp viết văn chuyên nghiệp. Ông kể lại quá trình luyện tập cho các cuộc thi marathon và ba môn phối hợp, đồng thời suy ngẫm về mối liên hệ giữa việc chạy bộ, kỷ luật bản thân và quá trình sáng tác văn chương. Cuốn sách mang tính tự sự, pha trộn giữa những chiêm nghiệm về tuổi tác, ý chí và triết lý sống của tác giả."],
      ["Lâu Đài Bay Của Pháp Sư Howl", "Diana Wynne Jones", undefined, "Tiểu thuyết kể về Sophie, cô gái lớn nhất trong ba chị em làm nghề thợ mũ, bị Phù thủy Hoang Mạc biến thành một bà lão do ghen tị. Để tìm cách phá bỏ lời nguyền, Sophie tìm đến lâu đài di động kỳ lạ của pháp sư Howl, một phù thủy trẻ nổi tiếng với tin đồn chuyên đánh cắp trái tim các cô gái, và trở thành người dọn dẹp trong lâu đài của anh. Qua thời gian sống cùng Howl và con quỷ lửa Calcifer, Sophie dần khám phá ra bí mật đằng sau lời nguyền của cả hai người và tìm được tình yêu đích thực."],
      ["Lũ Trẻ Nhà Penderwicks", "Jeanne Birdsall", undefined, "Tiểu thuyết kể về bốn chị em nhà Penderwicks - Rosalind, Skye, Jane và Batty - cùng người cha góa vợ trong kỳ nghỉ hè tại một khu điền trang tên Arundel. Tại đây, các cô bé kết bạn với Jeffrey, cậu con trai của bà chủ điền trang khó tính, và cùng nhau trải qua nhiều cuộc phiêu lưu, trò nghịch ngợm hồn nhiên của tuổi thơ. Câu chuyện khắc họa tình cảm gắn bó giữa các chị em cùng những bài học nhẹ nhàng về tình bạn và trưởng thành."],
      ["Chuyến Phiêu Lưu Của Edward Tulane", "Kate DiCamillo", undefined, "Tiểu thuyết kể về Edward Tulane, một chú thỏ đồ chơi bằng sứ kiêu ngạo và chỉ biết yêu thương bản thân, thuộc sở hữu của cô bé Abilene. Sau khi bị thất lạc trên biển trong một chuyến đi, Edward trải qua hành trình dài đầy gian truân, lần lượt được nhiều chủ nhân khác nhau nâng niu hoặc vứt bỏ. Qua những mất mát và chia ly trong hành trình, Edward dần học được ý nghĩa thật sự của tình yêu thương và sự gắn kết giữa con người."],
      ["Những Người Khốn Khổ", "Victor Hugo", undefined, "Tiểu thuyết kể về Jean Valjean, một cựu tù khổ sai bị kết án vì ăn cắp bánh mì, sau khi được một vị giám mục cảm hóa đã quyết tâm sống lương thiện và trở thành thị trưởng của một thị trấn dưới danh tính mới. Trong suốt cuộc đời, ông luôn bị viên thanh tra Javert truy đuổi ráo riết, đồng thời cưu mang Cosette, con gái của người phụ nữ bất hạnh Fantine, như con ruột của mình. Câu chuyện diễn ra trên nền bối cảnh nước Pháp đầu thế kỷ 19 với những biến động xã hội và cuộc khởi nghĩa của sinh viên Paris, khắc họa các chủ đề về công lý, cứu chuộc và lòng nhân ái."],
      ["Trăng Lặn", "John Steinbeck", undefined, "Tiểu thuyết kể về một thị trấn nhỏ ở châu Âu bị quân đội nước ngoài xâm chiếm và đặt dưới ách chiếm đóng trong Thế chiến thứ hai. Đại tá Lanser, chỉ huy quân chiếm đóng, và thị trưởng Orden đại diện cho người dân thị trấn dần rơi vào thế đối đầu khi người dân bắt đầu tổ chức các hoạt động kháng cự âm thầm. Tác phẩm khắc họa tinh thần bất khuất của người dân thường trước ách áp bức, cùng sự giằng xé tâm lý của cả những kẻ chiếm đóng."],
      ["Lolita", "Vladimir Nabokov", undefined, "Tiểu thuyết được kể qua lời tự thuật của Humbert Humbert, một giáo sư văn học trung niên mắc chứng ám ảnh bệnh hoạn với các bé gái tuổi vị thành niên. Humbert kết hôn với Charlotte Haze để được gần gũi con gái riêng của bà, Dolores, biệt danh Lolita, rồi sau khi Charlotte qua đời, hắn đưa Lolita đi khắp nước Mỹ trong một mối quan hệ lạm dụng kéo dài. Cuốn tiểu thuyết gây tranh cãi vì nội dung nhưng được đánh giá cao về nghệ thuật ngôn từ, khắc họa tâm lý bệnh hoạn và thao túng của kẻ ấu dâm qua giọng kể tự biện hộ đầy mê hoặc."],
      ["Người Truyền Ký Ức", "Lois Lowry", undefined, "Tiểu thuyết lấy bối cảnh một xã hội tương lai được kiểm soát chặt chẽ, nơi mọi cảm xúc, ký ức đau buồn và sự khác biệt đều bị loại bỏ để duy trì sự hoàn hảo và bình yên giả tạo. Jonas, cậu bé mười hai tuổi, được chọn làm Người Tiếp Nhận Ký Ức mới của cộng đồng, từ đó dần được truyền lại toàn bộ ký ức thật của nhân loại, bao gồm cả niềm vui, nỗi đau, chiến tranh và tình yêu, những thứ mà xã hội đã cố tình xóa bỏ. Khi nhận ra sự thật tàn khốc đằng sau vẻ ngoài hoàn hảo của cộng đồng, Jonas quyết định thực hiện một hành động liều lĩnh để thay đổi số phận của chính mình và mọi người."],
      ["Oscar Và Bà Áo Hồng", "Éric-Emmanuel Schmitt", undefined, "Tiểu thuyết kể về Oscar, một cậu bé mười tuổi mắc bệnh ung thư máu đang trong những ngày cuối đời tại bệnh viện. Theo lời khuyên của Bà Hồng, một tình nguyện viên chăm sóc bệnh nhân, Oscar bắt đầu viết thư cho Thượng Đế mỗi ngày, tưởng tượng mỗi ngày sống tương đương với mười năm cuộc đời để trải nghiệm trọn vẹn các giai đoạn của một kiếp người. Qua những lá thư hồn nhiên mà sâu sắc, cậu bé dần học cách đối diện với cái chết một cách bình thản và tìm thấy ý nghĩa trong quãng thời gian ngắn ngủi còn lại."],
      ["Peter Pan", "J.M. Barrie", undefined, "Tiểu thuyết kể về Peter Pan, cậu bé không bao giờ lớn sống tại vùng đất thần tiên Neverland cùng nàng tiên Tinker Bell và nhóm Lost Boys. Một đêm nọ, Peter bay đến nhà gia đình Darling và đưa ba chị em Wendy, John và Michael đến Neverland, nơi họ trải qua nhiều cuộc phiêu lưu cùng người da đỏ, nàng tiên cá và cuộc chiến với tên cướp biển độc ác Captain Hook. Cuối cùng, sau những cuộc phiêu lưu kỳ thú, Wendy và các em quyết định trở về nhà và trưởng thành, trong khi Peter Pan chọn ở lại Neverland để mãi mãi là một đứa trẻ."],
      ["Người Xa Lạ", "Albert Camus", undefined, "Tiểu thuyết kể về Meursault, một người đàn ông sống ở Algeria với thái độ dửng dưng, vô cảm trước mọi biến cố trong cuộc đời, kể cả cái chết của mẹ mình. Trong một buổi trưa nắng gắt trên bãi biển, Meursault bắn chết một người Ả Rập trong một khoảnh khắc bốc đồng không rõ động cơ rõ ràng. Tại phiên tòa xét xử, thái độ thờ ơ và không tỏ ra hối hận của anh trước cái chết của mẹ và tội ác của mình khiến anh bị kết án tử hình, qua đó tác phẩm khắc họa triết lý hiện sinh phi lý về thân phận con người."],
      ["Thời Khắc", "Michael Cunningham", undefined, "Tiểu thuyết đan xen câu chuyện của ba người phụ nữ ở ba thời điểm khác nhau trong thế kỷ 20: nhà văn Virginia Woolf đang viết cuốn tiểu thuyết Bà Dalloway tại Anh những năm 1920, một bà nội trợ tên Laura Brown đọc cuốn sách đó ở Los Angeles thập niên 1950, và Clarissa Vaughan, một phụ nữ hiện đại ở New York cuối thế kỷ 20 đang chuẩn bị một bữa tiệc cho người bạn cũ mắc bệnh AIDS. Ba câu chuyện tưởng chừng tách biệt nhưng có sự liên kết chặt chẽ qua chủ đề, biểu tượng và cấu trúc lấy cảm hứng từ Bà Dalloway của Virginia Woolf. Tác phẩm khám phá những trăn trở về ý nghĩa cuộc sống, sự tồn tại và những khoảnh khắc quyết định trong đời mỗi người phụ nữ."],
      ["Bí Ẩn Về Con Chó Lúc Nửa Đêm", "Mark Haddon", undefined, "Tiểu thuyết được kể qua lời của Christopher Boone, một cậu bé mười lăm tuổi mắc hội chứng tự kỷ có khả năng đặc biệt về toán học nhưng gặp khó khăn trong giao tiếp xã hội. Sau khi phát hiện con chó của hàng xóm bị giết chết bằng chĩa làm vườn, Christopher quyết định tự mình điều tra như một thám tử để tìm ra thủ phạm. Quá trình điều tra vô tình khiến cậu khám phá ra những bí mật đau lòng trong chính gia đình mình, buộc cậu phải một mình thực hiện chuyến đi đầy thử thách đến London."],
      ["Bố Là Bà Giúp Việc", "Anne Fine", undefined, "Tiểu thuyết kể về Daniel, một diễn viên đã ly hôn khao khát được gần gũi ba đứa con nhưng chỉ được phép thăm chúng rất hạn chế theo phán quyết ly hôn. Để có thể ở gần các con nhiều hơn, Daniel cải trang thành một bà giúp việc lớn tuổi tên Madame Doubtfire và xin vào làm việc ngay tại nhà vợ cũ của mình. Bằng vỏ bọc này, anh dần lấy lại được tình cảm gắn bó với các con, nhưng cũng phải đối mặt với nguy cơ bị lộ thân phận thật của mình."],
      ["Chuyện Người Tùy Nữ", "Margaret Atwood", undefined, "Tiểu thuyết lấy bối cảnh Cộng hòa Gilead, một xã hội toàn trị theo chủ nghĩa thần quyền cực đoan được thành lập ở nước Mỹ tương lai sau một cuộc khủng hoảng sinh sản trên diện rộng. Nhân vật chính Offred là một Tùy nữ, bị tước bỏ tên thật và mọi quyền tự do, chỉ còn giá trị duy nhất là mang thai và sinh con cho các gia đình quyền lực trong xã hội. Qua lời kể của Offred, tác phẩm phơi bày sự áp bức tàn bạo đối với phụ nữ và cảnh báo về nguy cơ của chủ nghĩa cực đoan tôn giáo và chính trị."],
      ["Cô Gái Chơi Dương Cầm", "Elfriede Jelinek", undefined, "Tiểu thuyết kể về Erika Kohut, một giáo viên dương cầm trung niên tại Vienna sống dưới sự kiểm soát nghẹt thở của người mẹ độc đoán, người luôn muốn con gái mình trở thành một nghệ sĩ dương cầm hoàn hảo. Đằng sau vẻ ngoài lạnh lùng, khắc kỷ, Erika giấu kín những ham muốn tình dục lệch lạc và khuynh hướng tự hành hạ bản thân, dần bộc lộ khi cô nảy sinh quan hệ với một học trò trẻ tuổi tên Walter Klemmer. Mối quan hệ giữa hai người ngày càng trở nên bệnh hoạn và bạo liệt, phơi bày những tổn thương tâm lý sâu sắc bị dồn nén suốt nhiều năm của Erika."],
      ["Hãy Đi Đặt Người Canh Gác", "Harper Lee", undefined, "Tiểu thuyết kể về Jean Louise Finch, biệt danh Scout khi còn nhỏ trong Giết Con Chim Nhại, nay đã trưởng thành, trở về thị trấn Maycomb ở Alabama để thăm người cha già Atticus Finch. Trong chuyến thăm, cô bàng hoàng phát hiện những quan điểm về chủng tộc của cha mình, người mà cô từng thần tượng như biểu tượng của công lý, không còn giống như hình ảnh cô ghi nhớ thời thơ ấu. Tác phẩm khắc họa cuộc khủng hoảng niềm tin của Scout khi đối diện với những giới hạn và mâu thuẫn trong con người mà cô từng xem là hoàn hảo."],
      ["Hồi Ức Của Một Geisha", "Arthur Golden", undefined, "Tiểu thuyết kể về cuộc đời Chiyo, một cô bé nghèo bị gia đình bán vào một kỹ viện geisha ở Kyoto những năm 1930, sau này được huấn luyện trở thành geisha nổi tiếng với nghệ danh Sayuri. Qua nhiều năm khổ luyện nghệ thuật múa hát, trà đạo và cách ứng xử của một geisha, Sayuri phải cạnh tranh với các đối thủ trong giới geisha để có được vị trí và sự bảo trợ từ những người đàn ông quyền thế. Xuyên suốt câu chuyện là tình cảm thầm kín của Sayuri dành cho một người đàn ông tốt bụng tên Chủ Tịch, người mà nàng luôn khao khát được ở bên."],
      ["Trường Hợp Kỳ Lạ Của Dr. Jekyll And Mr. Hyde", "Robert Louis Stevenson", undefined, "Tiểu thuyết kể về bác sĩ Henry Jekyll, một nhà khoa học đáng kính ở London, người bào chế ra một loại thuốc có khả năng tách biệt phần thiện và phần ác trong con người ông. Khi uống thuốc, Jekyll biến thành Edward Hyde, một kẻ nhỏ bé, xấu xa và tàn bạo, người dần dần gây ra hàng loạt tội ác ghê rợn. Theo thời gian, Jekyll ngày càng mất kiểm soát với việc biến đổi thành Hyde, dẫn đến kết cục bi thảm khi ranh giới giữa hai nhân cách của ông không còn có thể tách rời."],
      ["Kẻ Trộm Sách", "Markus Zusak", undefined, "Tiểu thuyết lấy bối cảnh nước Đức thời Thế chiến thứ hai, kể về Liesel Meminger, một cô bé được gửi đến sống với gia đình nuôi và bắt đầu học đọc, học viết thông qua những cuốn sách cô lấy trộm được. Gia đình nuôi của Liesel bí mật che giấu Max, một thanh niên Do Thái, trong hầm nhà, và Liesel dần trở nên thân thiết với anh qua tình yêu chung dành cho ngôn từ và sách vở. Câu chuyện được kể bởi Thần Chết, người quan sát và đồng cảm với số phận con người giữa bối cảnh chiến tranh tàn khốc."],
      ["Quả Chuông Ảo Mộng", "Sylvia Plath", undefined, "Tiểu thuyết mang tính tự truyện kể về Esther Greenwood, một cô gái trẻ tài năng giành được kỳ thực tập mơ ước tại một tạp chí ở New York vào mùa hè. Dù có vẻ ngoài thành công, Esther dần rơi vào trạng thái trầm cảm nặng nề, cảm thấy bị mắc kẹt như dưới một chiếc chuông thủy tinh ngăn cách cô với thế giới xung quanh. Cô trải qua giai đoạn khủng hoảng tâm lý nghiêm trọng, từng cố gắng tự tử và phải điều trị tại bệnh viện tâm thần, nơi cô dần tìm cách đối diện với căn bệnh của mình."],
      ["Xứ Con Người", "Antoine de Saint-Exupéry", undefined, "Đây là tập hồi ký gồm nhiều bài viết của Antoine de Saint-Exupéry, phi công kiêm nhà văn Pháp, kể lại những trải nghiệm của ông trong nghề bay thư tín qua sa mạc Sahara và dãy Andes vào những năm 1920-1930. Tác giả kể lại vụ tai nạn máy bay khiến ông cùng người bạn đồng hành sống sót lạc giữa sa mạc nhiều ngày không có nước uống trước khi được cứu. Qua những trải nghiệm hiểm nguy giữa thiên nhiên khắc nghiệt, tác phẩm suy ngẫm về tình đồng loại, lòng dũng cảm và trách nhiệm của con người."],
      ["Châu Phi Nghìn Trùng", "Isak Dinesen", undefined, "Đây là hồi ký của nữ nhà văn Đan Mạch Karen Blixen, bút danh Isak Dinesen, kể về những năm tháng bà sinh sống và điều hành một đồn điền cà phê tại Kenya, châu Phi, đầu thế kỷ 20. Bà kể lại cuộc sống gắn bó với vùng đất và con người châu Phi, đặc biệt là mối quan hệ với người thợ săn người Anh Denys Finch Hatton, cũng như những khó khăn trong việc duy trì đồn điền. Cuốn hồi ký khép lại khi đồn điền phá sản buộc bà phải rời châu Phi trở về Đan Mạch, mang theo nỗi luyến tiếc sâu sắc với vùng đất này."],
      ["The Martian", "Andy Weir", undefined, "Tiểu thuyết kể về Mark Watney, một phi hành gia kiêm nhà thực vật học bị đồng đội bỏ lại một mình trên sao Hỏa sau khi họ tưởng anh đã chết trong một trận bão cát dữ dội. Với nguồn lương thực và thiết bị hạn chế, Watney phải vận dụng kiến thức khoa học để trồng khoai tây, sản xuất nước và duy trì sự sống trong khi tìm cách liên lạc với Trái Đất. Trong khi đó, NASA và các đồng đội cũ nỗ lực tìm cách giải cứu anh trước khi nguồn sống trên sao Hỏa cạn kiệt."],
      ["Hiệu Sách Nhỏ Ở Paris", "Nina George", undefined, "Tiểu thuyết kể về Jean Perdu, chủ nhân một hiệu sách nổi trên sông Seine ở Paris, người có khả năng đặc biệt trong việc kê đơn thuốc là những cuốn sách phù hợp để chữa lành nỗi đau tinh thần cho khách hàng, nhưng lại không thể chữa lành nỗi đau của chính mình sau khi bị người yêu bỏ rơi nhiều năm trước. Khi tình cờ đọc được bức thư bị giấu kín suốt hai mươi năm, ông quyết định nhổ neo con thuyền hiệu sách, cùng một số người bạn mới quen thực hiện chuyến hành trình xuôi theo các dòng sông nước Pháp để tìm lại sự thật về mối tình đã mất. Chuyến đi trở thành hành trình chữa lành giúp Jean Perdu học cách đối diện với quá khứ và mở lòng đón nhận tình yêu mới."],
      ["Find Me (Call Me By Your Name)", "André Aciman", undefined, "Tiểu thuyết là phần tiếp theo của Gọi Em Bằng Tên Anh, kể về cuộc sống của các nhân vật nhiều năm sau mùa hè định mệnh ở Ý. Phần đầu tập trung vào Samuel, cha của Elio, khi ông gặp gỡ một người phụ nữ trẻ trên chuyến tàu và bắt đầu mối quan hệ mới, còn các phần sau theo chân Elio tại Paris và cuối cùng là cuộc tái ngộ giữa Elio và Oliver sau nhiều năm xa cách. Tác phẩm tiếp tục khai thác các chủ đề về tình yêu, thời gian và ký ức đã làm nên thành công của phần đầu tiên."],
    ],
  },
{
    t: "IX. Khác",
    n: 36,
    items: [
      ["Mùa Thu Của Cây Dương", "Kazumi Yumoto", undefined, "Cuốn sách kể về Chiaki, một cô bé mất cha, cùng mẹ chuyển đến sống trong một khu nhà trọ cũ do một bà lão tên Popura trông coi. Bà lão kể cho Chiaki nghe rằng khi con người chết đi, họ sẽ hóa thành mây trên bầu trời. Qua những ngày tháng bên nhau, Chiaki dần học cách đối diện với nỗi đau mất mát và chuẩn bị tinh thần cho sự ra đi của người bà mà em yêu quý."],
      ["Little Men, Jo's Boys", "Louisa May Alcott", undefined, "Đây là hai cuốn tiếp theo của bộ tiểu thuyết bắt đầu từ Little Women, xoay quanh Jo March khi trưởng thành và cùng chồng là giáo sư Bhaer mở ngôi trường Plumfield dành cho các cậu bé. Little Men kể về cuộc sống, những bài học và tình bạn của đám học trò tại ngôi trường này. Jo's Boys tiếp nối câu chuyện nhiều năm sau, khi những cậu học trò ngày nào đã trưởng thành và theo đuổi những con đường riêng trong cuộc sống."],
      ["Momo", "Michael Ende", undefined, "Momo là cô bé mồ côi sống trong một đấu trường La Mã đổ nát, có khả năng đặc biệt là lắng nghe người khác một cách chân thành. Khi những Người Xám bí ẩn xuất hiện và dụ dỗ người dân thành phố tiết kiệm thời gian bằng cách gửi vào ngân hàng thời gian, cuộc sống của mọi người trở nên vội vã và lạnh lùng. Momo, với sự giúp đỡ của Thầy Hora và chú rùa Cassiopeia, đã lên đường giải cứu thời gian đã mất của con người."],
      ["Máu Lạnh", "Truman Capote", undefined, "Máu Lạnh là tác phẩm phi hư cấu kể lại vụ thảm sát gia đình Clutter tại một thị trấn nhỏ ở Kansas năm 1959. Truman Capote tái hiện chi tiết quá trình điều tra, chân dung hai kẻ sát nhân Perry Smith và Dick Hickock, cùng những gì dẫn họ đến tội ác. Cuốn sách được coi là một trong những tác phẩm tiên phong của thể loại tiểu thuyết phi hư cấu (nonfiction novel)."],
      ["Mãi Yêu Con", "Robert Munsch", undefined, "Cuốn sách tranh kể về một người mẹ mỗi đêm đều bế con trai và hát một bài hát ru thể hiện tình yêu vô điều kiện dành cho con. Qua từng giai đoạn cuộc đời, từ khi con còn là em bé đến khi trưởng thành rời xa mẹ, người mẹ vẫn lặng lẽ đến bên và hát bài hát ấy. Khi mẹ già yếu, người con đã trở lại chăm sóc và hát lại chính bài hát đó cho mẹ, khép lại vòng tuần hoàn của tình yêu thương."],
      ["Nanh Trắng", "Jack London", undefined, "Nanh Trắng kể về cuộc đời một con sói lai chó hoang sống ở vùng Yukon khắc nghiệt trong thời kỳ đổ xô tìm vàng. Từ một con vật hoang dã bị con người ngược đãi, Nanh Trắng dần được thuần hóa bởi Weedon Scott, người đối xử với nó bằng sự tử tế và kiên nhẫn. Câu chuyện khắc họa quá trình chuyển hóa từ bản năng hoang dã sang sự trung thành và gắn bó với con người."],
      ["Sherlock Holmes", "Arthur Conan Doyle", undefined, "Đây là series truyện trinh thám kinh điển xoay quanh nhà thám tử tài ba Sherlock Holmes và người bạn đồng hành, bác sĩ Watson, tại London thời Victoria. Bằng khả năng suy luận logic sắc bén và quan sát tỉ mỉ, Holmes lần lượt phá giải những vụ án bí ẩn mà cảnh sát bó tay. Các câu chuyện được kể lại qua góc nhìn của Watson, người ghi chép lại những cuộc phiêu lưu phá án của hai người."],
      ["Con Của Noé", "Éric-Emmanuel Schmitt", undefined, "Câu chuyện lấy bối cảnh nước Bỉ bị Đức Quốc xã chiếm đóng, kể về cậu bé Do Thái Joseph được cha xứ Pons giấu trong một trại trẻ mồ côi Công giáo để tránh bị truy bắt. Tại đây, cha Pons bí mật che giấu nhiều trẻ em Do Thái khác dưới vỏ bọc trẻ Công giáo, đồng thời dạy Joseph về cội nguồn tôn giáo thực sự của mình. Cuốn sách khắc họa tình người và sự khoan dung tôn giáo giữa thời chiến tranh tàn khốc."],
      ["Coraline", "Neil Gaiman", undefined, "Coraline là một cô bé chuyển đến sống trong một căn hộ cũ và tình cờ phát hiện một cánh cửa dẫn đến thế giới song song giống hệt nhà mình. Ở đó, cô gặp \"Người Mẹ Khác\" với đôi mắt là hai chiếc khuy áo, người muốn giữ Coraline lại mãi mãi bằng những lời dụ dỗ ngọt ngào. Khi nhận ra bản chất nguy hiểm của thế giới ấy, Coraline phải dùng trí thông minh và lòng dũng cảm để giải cứu bản thân và cha mẹ thật của mình."],
      ["Hóa Thân", "Franz Kafka", undefined, "Hóa Thân kể về Gregor Samsa, một nhân viên bán hàng, bỗng một sáng thức dậy và phát hiện mình đã biến thành một con côn trùng khổng lồ. Sự biến đổi này khiến anh mất khả năng lao động, trở thành gánh nặng và nỗi xấu hổ cho gia đình. Qua đó, tác phẩm khắc họa sự cô lập, tha hóa của con người trong xã hội hiện đại và mối quan hệ gia đình đầy rạn nứt."],
      ["Hẹn Em Ngày Đó", "Guillaume Musso"],
      ["Nghe Mùi Kết Thúc", "Julian Barnes", undefined, "Tony Webster, một người đàn ông đã về hưu, bất ngờ nhận được một khoản thừa kế nhỏ từ mẹ của người bạn gái cũ thời đại học. Sự kiện này khiến ông phải nhìn lại những ký ức về thời trẻ, về người bạn thân Adrian đã tự tử, và về mối quan hệ với Veronica năm xưa. Trong quá trình lần tìm lại quá khứ, Tony dần nhận ra ký ức của mình không hoàn toàn đáng tin cậy và có phần trách nhiệm trong bi kịch mà ông từng phủ nhận."],
      ["Kira-Kira", "Cynthia Kadohata", undefined, "Câu chuyện kể về Katie, một cô bé người Mỹ gốc Nhật, và người chị gái Lynn trong một gia đình lao động nghèo ở vùng nông thôn Georgia. Lynn luôn dạy Katie nhìn cuộc sống lấp lánh (kira-kira) dù hoàn cảnh gia đình khó khăn, nhưng rồi Lynn mắc bệnh ung thư hạch. Cuốn sách khắc họa tình chị em sâu sắc và hành trình Katie trưởng thành khi đối diện với bệnh tật và sự mất mát của chị mình."],
      ["35 Ki Lô Hy Vọng", "Anna Gavalda", undefined, "Grégoire là một cậu bé học kém, chán ghét trường lớp và thường xuyên bị đúp lớp, khiến cha mẹ thất vọng. Người duy nhất thực sự thấu hiểu và yêu thương cậu là ông ngoại Léon, một người thợ mộc tài hoa nhưng ít học. Qua tình cảm với ông, Grégoire dần tìm lại niềm tin vào bản thân và khám phá ra đam mê, hướng đi riêng cho cuộc đời mình."],
      ["Ami - Cậu Bé Vì Sao", "Enrique Barrios", undefined, "Cuốn sách kể về một cậu bé tình cờ gặp Ami, một sinh vật ngoài hành tinh mang hình hài trẻ nhỏ đến từ một hành tinh văn minh cao. Ami đưa cậu bé lên phi thuyền, cùng du hành qua các vì sao và chia sẻ những triết lý về tình yêu thương, sự tiến hóa tâm linh và bản chất của vũ trụ. Chuyến phiêu lưu giúp cậu bé thay đổi cách nhìn về cuộc sống, con người và vị trí của Trái Đất trong vũ trụ bao la."],
      ["Ở Nhà Với Madame Chic", "Jennifer L. Scott", undefined, "Đây là phần tiếp theo của cuốn Lessons from Madame Chic, trong đó tác giả Jennifer L. Scott chia sẻ những bài học về lối sống tinh tế, giản dị kiểu Pháp mà bà học được khi sống cùng một gia đình Paris. Cuốn sách tập trung vào cách tổ chức, chăm chút không gian sống trong nhà sao cho vừa thanh lịch vừa thực tế. Tác giả đưa ra những gợi ý cụ thể về nội trợ, trang trí và thói quen sinh hoạt để xây dựng một tổ ấm đẹp đẽ, có gu."],
      ["Ba Sai Lầm Của Đời Tôi", "Chetan Bhagat", undefined, "Câu chuyện xoay quanh ba người bạn thân ở thành phố Ahmedabad, Ấn Độ, cùng nhau mở một cửa hàng thể thao kiêm học viện dạy cricket. Trên hành trình theo đuổi ước mơ kinh doanh, tình bạn của họ bị thử thách bởi tình yêu, tôn giáo và chính trị. Câu chuyện diễn ra trên nền các cuộc bạo động tôn giáo năm 2002 tại bang Gujarat, tác động sâu sắc đến số phận của cả ba."],
      ["Bob - Chú Mèo Đường Phố", "James Bowen", undefined, "Đây là hồi ký của James Bowen, một nghệ sĩ đường phố ở London đang trong quá trình cai nghiện ma túy. Cuộc sống của anh thay đổi khi anh cứu một chú mèo hoang bị thương và đặt tên là Bob, rồi hai người bạn trở nên không thể tách rời. Sự đồng hành của Bob đã giúp James dần lấy lại kỷ luật, trách nhiệm và niềm tin để xây dựng lại cuộc đời."],
      ["Daring Greatly", "Brené Brown", undefined, "Trong cuốn sách này, nhà nghiên cứu Brené Brown lập luận rằng sự tổn thương (vulnerability) không phải là điểm yếu mà là nguồn gốc của lòng can đảm, sự sáng tạo và kết nối chân thật. Bà phân tích cách nỗi sợ hãi và cảm giác xấu hổ khiến con người né tránh rủi ro cảm xúc trong công việc, tình yêu và nuôi dạy con cái. Cuốn sách đưa ra những chỉ dẫn để sống \"dấn thân trọn vẹn\", dám thể hiện bản thân dù có thể phải đối mặt với thất bại hay phán xét."],
      ["The Force - Sát Thủ Bán Hàng", "David Dorsey", undefined, "Cuốn sách theo chân một đội ngũ nhân viên bán hàng xuất sắc của hãng Xerox tại Cleveland trong suốt một năm làm việc. David Dorsey ghi lại áp lực, chiến thuật và tâm lý của những \"sát thủ bán hàng\" trong cuộc đua đạt chỉ tiêu doanh số khắc nghiệt. Qua đó, tác phẩm phơi bày mặt trái đầy cạnh tranh và căng thẳng của nghề bán hàng chuyên nghiệp tại Mỹ."],
      ["The Gifts Of Imperfection", "Brené Brown", undefined, "Brené Brown trình bày mười cột mốc hướng dẫn giúp con người buông bỏ áp lực phải trở nên hoàn hảo để sống một cuộc đời trọn vẹn (wholehearted). Bà khuyến khích độc giả chấp nhận sự không hoàn hảo của bản thân, nuôi dưỡng lòng can đảm, sự trắc ẩn và kết nối với người khác. Cuốn sách kết hợp nghiên cứu học thuật với trải nghiệm cá nhân để đưa ra những bài học thực tiễn về giá trị bản thân."],
      ["Khi Ta Mơ Quá Lâu", "Goh Poh Seng", undefined, "Đây là một trong những tiểu thuyết hiện đại đầu tiên của Singapore, kể về Kwang Meng, một chàng trai trẻ vừa tốt nghiệp và bước vào đời. Anh cảm thấy chán nản và lạc lõng trước những kỳ vọng gia đình, công việc tẻ nhạt và xã hội Singapore đang chuyển mình sau độc lập. Cuốn sách khắc họa khủng hoảng tuổi trẻ và câu hỏi về ý nghĩa cuộc sống của một thế hệ thanh niên thời hậu thuộc địa."],
      ["The Signature Of All Things", "Elizabeth Gilbert", undefined, "Tiểu thuyết kể về cuộc đời Alma Whittaker, một nhà thực vật học sống vào thế kỷ 19, con gái của một thương nhân giàu có. Alma dành cả đời nghiên cứu về rêu và những quy luật tiến hóa của tự nhiên, đi trước cả một số phát hiện khoa học đương thời. Song song với hành trình khoa học, cuốn sách còn khắc họa những khát khao tình cảm, tri thức và khát vọng thấu hiểu thế giới của bà."],
      ["Gieo Trồng Trên Sa Mạc", "Masanobu Fukuoka", undefined, "Cuốn sách ghi lại hành trình của Masanobu Fukuoka, cha đẻ phương pháp nông nghiệp tự nhiên, khi ông mang triết lý canh tác không cày xới, không phân bón hóa học đến các vùng đất khô cằn ở châu Phi, Ấn Độ và nhiều nơi khác. Ông chia sẻ kinh nghiệm gieo hạt giống trên sa mạc nhằm phục hồi thảm thực vật và chống sa mạc hóa. Tác phẩm tiếp nối tinh thần của Cuộc Cách Mạng Một Cọng Rơm, mở rộng ứng dụng thực tiễn của nông nghiệp tự nhiên ra quy mô toàn cầu."],
      ["Đấu Trường Sinh Tử", "Suzanne Collins", undefined, "Câu chuyện lấy bối cảnh Panem, một quốc gia hậu tận thế được chia thành Capitol giàu có và mười hai quận nghèo khó. Hằng năm, mỗi quận phải cử hai thiếu niên tham gia Đấu Trường Sinh Tử, một cuộc thi đấu sinh tồn đến chết được truyền hình trực tiếp. Katniss Everdeen tình nguyện thay em gái tham gia trò chơi tàn khốc này, và hành trình sinh tồn của cô dần trở thành ngọn lửa châm ngòi cho một cuộc nổi dậy."],
      ["Đỏ Trỗi Dậy", "Pierce Brown", undefined, "Darrow là một thợ mỏ thuộc tầng lớp \"Đỏ\" thấp kém nhất, sống và làm việc dưới lòng đất sao Hỏa với niềm tin rằng công việc của họ giúp cải tạo hành tinh cho loài người. Sau cái chết của vợ vì phản kháng bất công, Darrow phát hiện sự thật bị che giấu và được một tổ chức nổi dậy cải trang thành người thuộc tầng lớp \"Vàng\" thống trị. Anh phải len lỏi vào thế giới thượng lưu đầy âm mưu để từ bên trong phá vỡ hệ thống phân cấp xã hội hà khắc."],
      ["Tấm Vải Đỏ", "Hồng Nương Tử"],
      ["Nỗi Đau Của Đom Đóm", "QCN"],
      ["Kỳ Án Ánh Trăng", "QCN"],
      ["Luân Hồi: Đau Thương Đến Chết", "QCN"],
      ["Wonderful Life: The Burgess Shale And The Nature Of History", "Stephen Jay Gould", undefined, "Stephen Jay Gould kể về hệ hóa thạch Burgess Shale ở Canada, nơi lưu giữ dấu tích của vô số sinh vật kỳ lạ từ thời kỳ bùng nổ sự sống kỷ Cambri. Ông thuật lại quá trình các nhà cổ sinh vật học nghiên cứu lại và diễn giải những hóa thạch này, phát hiện ra sự đa dạng hình thái vượt xa những gì từng nghĩ trước đó. Từ đó, Gould đưa ra luận điểm về tính ngẫu nhiên của lịch sử tiến hóa, rằng nếu \"cuộn lại băng ghi hình sự sống\" thì kết quả có thể hoàn toàn khác."],
      ["The World Is What It Is (Biography Of V.S. Naipaul)", "Patrick French", undefined, "Đây là cuốn tiểu sử chính thức về nhà văn đoạt giải Nobel V.S. Naipaul, được viết dựa trên quyền tiếp cận đầy đủ vào thư từ, nhật ký riêng tư của ông. Patrick French tái hiện cuộc đời Naipaul từ Trinidad đến nước Anh, sự nghiệp văn chương lừng lẫy cùng những mối quan hệ cá nhân đầy sóng gió. Cuốn sách nổi bật vì sự thẳng thắn khi phơi bày cả những mặt tối trong tính cách và cuộc sống riêng tư của nhà văn."],
      ["Làm Giàu Theo Cách Bá Đạo", "Jen Sincero", undefined, "Jen Sincero chỉ ra những niềm tin giới hạn về tiền bạc mà nhiều người vô thức mang theo từ nhỏ, khiến họ khó đạt được sự sung túc tài chính. Bà kết hợp tư duy tích cực, luật hấp dẫn và những bài tập thực hành cụ thể để giúp độc giả thay đổi tư duy về tiền bạc. Cuốn sách hướng đến việc giúp người đọc xây dựng thói quen và tâm lý cần thiết để kiếm tiền và làm giàu tự tin hơn."],
      ["How To Ace English", "Workman Publishing"],
      ["How To Live On 24 Hours A Day", "Arnold Bennett", undefined, "Cuốn sách nhỏ này của Arnold Bennett bàn về cách con người sử dụng quỹ thời gian ít ỏi ngoài giờ làm việc sao cho hiệu quả. Ông cho rằng dù ai cũng chỉ có 24 giờ mỗi ngày, phần lớn thời gian rảnh rỗi lại bị lãng phí một cách vô thức. Tác giả đưa ra những lời khuyên thiết thực về việc lên kế hoạch, đọc sách và trau dồi bản thân để sống một cuộc đời trọn vẹn hơn."],
      ["The Wisdom Of The Enneagram", "Don Richard Riso", "Đang đọc (50%)", "Cuốn sách giới thiệu hệ thống Enneagram, một công cụ phân loại tính cách con người thành chín kiểu người khác nhau. Don Richard Riso cùng Russ Hudson mô tả chi tiết đặc điểm, nỗi sợ hãi cốt lõi và động lực của từng kiểu tính cách, cùng các mức độ phát triển tâm lý từ lành mạnh đến bất ổn. Cuốn sách còn đưa ra những chỉ dẫn thực hành để mỗi người ứng dụng Enneagram vào hành trình phát triển bản thân và đời sống tinh thần."],
    ],
  },
];

/* ============================================================
   RENDER HELPERS
   ============================================================ */
function renderItems(items) {
  return (
    <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "grid", gridTemplateColumns: "1fr", gap: 9 }}>
      {items.map(([title, meta, note, summary], i) => (
        <li key={i} style={{ borderLeft: `2px solid ${LINE}`, paddingLeft: 11 }}>
          <div style={{ fontSize: 14.3, lineHeight: 1.42 }}>
            <span style={{ fontWeight: 600 }}>{title}</span>
            {meta && (
              <span style={{ color: MUTE, fontFamily: SANS, fontSize: 12.3 }}> · {meta}</span>
            )}
          </div>
          {summary && (
            <div style={{ fontFamily: SANS, fontSize: 12.2, color: NOTE, lineHeight: 1.55, marginTop: 4, fontStyle: "italic" }}>
              {summary}
            </div>
          )}
          {note && (
            <div style={{ fontFamily: SANS, fontSize: 12.2, color: NOTE, lineHeight: 1.55, marginTop: 3, fontStyle: "italic" }}>
              “{note}”
            </div>
          )}
        </li>
      ))}
    </ul>
  );
}

function GroupCard({ group, isOpen, onToggle }) {
  return (
    <div style={{ border: `1px solid ${LINE}`, borderRadius: 8, background: CARD, overflow: "hidden" }}>
      <button
        onClick={onToggle}
        style={{
          width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between",
          padding: "12px 16px", background: isOpen ? `${ACCENT}0F` : "transparent", border: "none",
          cursor: "pointer", fontFamily: SANS, textAlign: "left",
        }}
      >
        <span style={{ fontWeight: 700, fontSize: 13.3, color: INK }}>{group.t}</span>
        <span style={{ display: "flex", alignItems: "center", gap: 9, flexShrink: 0, marginLeft: 10 }}>
          <span style={{ fontSize: 11, color: MUTE, fontWeight: 700, background: `${ACCENT}14`, padding: "2px 7px", borderRadius: 10 }}>
            {group.n}
          </span>
          <span style={{ display: "inline-block", transform: isOpen ? "rotate(180deg)" : "none", transition: "transform .15s", color: MUTE, fontSize: 11 }}>
            ▾
          </span>
        </span>
      </button>
      {isOpen && (
        <div style={{ padding: "6px 16px 16px" }}>
          {group.sub ? (
            <div style={{ display: "grid", gap: 16 }}>
              {group.sub.map((s, i) => (
                <div key={i}>
                  {s.t && (
                    <div style={{ fontFamily: SANS, fontSize: 10.5, letterSpacing: "0.06em", textTransform: "uppercase", color: ACCENT, fontWeight: 700, marginBottom: 8 }}>
                      {s.t}
                    </div>
                  )}
                  {renderItems(s.items)}
                </div>
              ))}
            </div>
          ) : (
            renderItems(group.items)
          )}
        </div>
      )}
    </div>
  );
}

/* ============================================================
   MAIN
   ============================================================ */
export default function Book() {
  const [query, setQuery] = useState("");
  const [openMap, setOpenMap] = useState({ 0: true });

  const toggleGroup = (idx) => {
    setOpenMap((prev) => ({ ...prev, [idx]: !prev[idx] }));
  };

  const flatMatches = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return null;
    const out = [];
    BOOKS.forEach((g) => {
      const pushFrom = (items, subLabel) => {
        items.forEach(([title, meta, note, summary]) => {
          const hay = `${title} ${meta || ""} ${note || ""} ${summary || ""}`.toLowerCase();
          if (hay.includes(q)) out.push({ title, meta, note, summary, group: g.t, sub: subLabel });
        });
      };
      if (g.sub) g.sub.forEach((s) => pushFrom(s.items, s.t));
      else pushFrom(g.items, null);
    });
    return out;
  }, [query]);

  return (
    <div style={{ fontFamily: SERIF, background: PAPER, color: INK }}>
      <div style={{ padding: "26px 32px 60px", maxWidth: 1600, margin: "0 auto" }}>
        <div style={{ marginBottom: 16 }}>
          <h1 style={{ fontSize: 29, lineHeight: 1.16, margin: 0, fontWeight: 600, letterSpacing: "-0.01em" }}>
            Book
          </h1>
        </div>

        <div style={{ marginBottom: 18 }}>
          <div style={{ fontStyle: "italic", fontSize: 14.8, lineHeight: 1.62, borderLeft: `3px solid ${ACCENT}`, paddingLeft: 14 }}>
            {INTRO}
          </div>
          <div style={{ fontFamily: SANS, fontSize: 12.3, color: MUTE, marginTop: 9 }}>
            “All that we love deeply becomes part of us.” — Helen Keller
          </div>
        </div>

        <input
          type="text"
          placeholder="Tìm sách, tác giả..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          style={{
            width: "100%", boxSizing: "border-box", fontFamily: SANS, fontSize: 13.5,
            padding: "10px 14px", borderRadius: 8, border: `1px solid ${LINE}`, marginBottom: 20,
            outline: "none", background: CARD, color: INK,
          }}
        />

        {flatMatches ? (
          <div style={{ display: "grid", gap: 10 }}>
            <div style={{ fontFamily: SANS, fontSize: 12, color: MUTE }}>{flatMatches.length} kết quả</div>
            {flatMatches.map((m, i) => (
              <div key={i} style={{ borderLeft: `2px solid ${ACCENT}`, paddingLeft: 11 }}>
                <div style={{ fontFamily: SANS, fontSize: 10.3, color: MUTE, textTransform: "uppercase", letterSpacing: "0.05em" }}>
                  {m.group}
                  {m.sub ? ` · ${m.sub}` : ""}
                </div>
                <div style={{ fontSize: 14.3 }}>
                  <span style={{ fontWeight: 600 }}>{m.title}</span>
                  {m.meta && <span style={{ color: MUTE, fontFamily: SANS, fontSize: 12.3 }}> · {m.meta}</span>}
                </div>
                {m.summary && (
                  <div style={{ fontFamily: SANS, fontSize: 12.2, color: NOTE, fontStyle: "italic", marginTop: 4 }}>
                    {m.summary}
                  </div>
                )}
                {m.note && (
                  <div style={{ fontFamily: SANS, fontSize: 12.2, color: NOTE, fontStyle: "italic", marginTop: 3 }}>
                    “{m.note}”
                  </div>
                )}
              </div>
            ))}
          </div>
        ) : (
          <div style={{ display: "grid", gap: 12 }}>
            {BOOKS.map((g, i) => (
              <GroupCard key={i} group={g} isOpen={!!openMap[i]} onToggle={() => toggleGroup(i)} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
